packages/dsh-notifier/src/server/config/.source:
/**
 * config 域：外部输入 → 合法设置。三个来源（磁盘配置文件、组合层 entry、HTTP patch）都**不受信**，这里是它们进入
 * 设置模型的唯一闸门。三道工序不可互换：归一化**永不失败**、校验**只审显式提交**（缺键不是错误）、净化**只留认识的键**。
 */
import {
  BARK_KNOWN_KEYS,
  BARK_LEVELS,
  BARK_LEVELS_LIMIT,
  BARK_TIMEOUT_MS_LIMIT,
  BUILTIN_CHANNEL_TYPES,
  HISTORY_MAX_AGE_DAYS_LIMIT,
  REQUIRED_KEYS,
  WEBHOOK_AUTHS,
  WEBHOOK_KNOWN_KEYS,
  WEBHOOK_PRESETS,
  WEBHOOK_TEMPLATE_MAX_CHARS,
  isClockText,
  isSoundId,
} from "../../../../shared/interface.ts";
import { DEFAULT_CONFIG } from "../model/index.ts";
import { QUIET_WINDOWS_LIMIT } from "../model/type.ts";
import type {
  BarkChannelConfig,
  BarkLevel,
  BrowserChannelConfig,
  BuiltinChannelType,
  ChannelConfig,
  NotifyConfig,
  QuietHoursConfig,
  QuietWindow,
  RawSettingValue,
  SettingsPatch,
  SoundSetting,
  StoredSettings,
  SystemChannelConfig,
  WebhookChannelConfig,
} from "../model/type.ts";
import type { ValidationResult } from "./type.ts";

// ---------------------------------------------------------------- 合法域

// 内置音色白名单的事实源在 src/shared/sounds.ts（两端共享面），本域只消费：
// 写入口径与设置页的选项必须是同一份白名单，各写一份就会出现「页面选得到、宿主拒收」。
// 「白名单 ⊆ 音色表」这条不变量由 test/unit/shared/sounds.test.ts 守着。

// 内置频道类型的事实源在 src/shared/channels.ts（顺序即卡片顺序）：它们恒在场，是 `channels` 里
// 唯一不可删除的项——身份由 `type` 唯一确定。

/** bark 紧急度白名单、频道已知键、必填键、**尺寸上界**（`WEBHOOK_TEMPLATE_MAX_CHARS` /
 * `BARK_LEVELS_LIMIT`）的事实源都在 src/shared/config-schema.ts（两端共享面）：
 * 写入口径与设置页的选项必须是同一份，各写一份就会出现「页面选得到、宿主拒收」。本域只消费。
 *
 * 尺寸上界（#1016 S2）此前在本域就地写字面量，理由是「本轮不扩两端共享 schema」——那份「刻意」
 * 正是 S1 要消灭的第二事实源：客户端将来给这两个输入框加同源约束时只能来本域抄一份。
 * 两条尺寸判据的语义是**「拒新增、不动存量」**：本次提交的值超限即 400，沿用存量的旧值不重判
 * （判据的 `inherited` 面，见 validateChannel）；0.2.9 形态清理按同一口径不删它们。 */

// webhook 认证方式与预设白名单的事实源在 src/shared/webhooks.ts（两端共享面）：设置页的选项与
// 写入口径必须是同一份，各写一份就会出现「页面选得到、宿主拒收」。

/** `"HH:MM"` 二十四小时制：事实源在 src/shared/quiet.ts（`isClockText`），两端同源。 */

/**
 * 频道实例里**合法的凭据只能走已知字段**（bark 的 `deviceKey`、webhook 的 `token`/`password`/`headerValue`），
 * 这些凭据别名键在写入口径直接**拒绝**而不是静默剔除——静默剔除会让用户以为设置生效了。
 *
 * 导出是为了让判据按清单表驱动：README 的「保留键写拒」与这份清单必须是同一份事实源。
 */
export const BARK_RESERVED_KEYS: readonly string[] = ["device_key", "device_keys", "ciphertext"];

/** webhook 侧的凭据别名键；与 `BARK_RESERVED_KEYS` 同语义（见上）。 */
export const WEBHOOK_RESERVED_KEYS: readonly string[] = [
  "auth_token",
  "access_token",
  "bearer_token",
  "api_key",
  "apikey",
  "client_secret",
  "secret",
  "password_hash",
];

/**
 * 契约认识的键。从默认设置派生而不是另抄一份清单：模型新增键时白名单自动跟上，否则
 * 就是「加了键却忘了加白名单，该键永远写不进去」这种沉默故障。
 */
const CONFIG_KEYS: readonly string[] = Object.keys(DEFAULT_CONFIG);

/**
 * 只接受布尔值的键。
 *
 * 导出而非私有：门禁 `config-matrix` 要按真实取值断言「这份清单是默认设置的子集且值都是布尔」，
 * 让它读定义处才是唯一事实源——照抄一份给门禁，两边迟早各说各话。
 */
export const BOOLEAN_KEYS: readonly string[] = [
  "notifyAsk",
  "notifyQuestion",
  "notifyTaskDone",
  "notifySubagentDone",
  "notifyTaskError",
  "notifyTurnEnd",
];

/** 0.2.3 顶层渠道键的退役话术：0.2.4 起它们由 upgrade 域在装配期搬进 `channels` 的内置条目并删除。 */
const MOVED_INTO_CHANNELS_HINT =
  "该键在 0.2.4 升级时已移入渠道条目；页面停留在升级前时，刷新后重试";

/** `maxConnections` 的退役话术：0.2.5 移除了连接上限机制，本键没有后继键——说成「已移入渠道条目」会把用户引到另一种原因上。 */
const CONNECTION_CAP_REMOVED_HINT =
  "该键在 0.2.5 升级时已随 SSE 连接上限机制一并移除；页面停留在升级前时，刷新后重试";

/**
 * 退役键：**曾经**是合法配置键、现已没有值语义的键，写面一律 400 拒收，且每键自带拒收话术。
 *
 * 为什么拒而不是当陌生键放行：陌生键是留给未来版本的空间，而这一批是**已经搬走 / 已经删除**的键——
 * 静默放行会让停留在升级前页面上的旧客户端以为保存成功了。话术逐键给出而不是共用一句：0.2.3 那批只是
 * 搬了家，`maxConnections` 是机制整体移除，共用一句会把后者引到错误的原因上。
 */
export const RETIRED_KEYS: Readonly<Record<string, string>> = {
  systemEnabled: MOVED_INTO_CHANNELS_HINT,
  browserEnabled: MOVED_INTO_CHANNELS_HINT,
  systemNotify: MOVED_INTO_CHANNELS_HINT,
  browserNotify: MOVED_INTO_CHANNELS_HINT,
  notifyWhenVisible: MOVED_INTO_CHANNELS_HINT,
  notifySound: MOVED_INTO_CHANNELS_HINT,
  browserSound: MOVED_INTO_CHANNELS_HINT,
  systemSound: MOVED_INTO_CHANNELS_HINT,
  maxConnections: CONNECTION_CAP_REMOVED_HINT,
};

/**
 * 非负整数键及其上界（越界视为非法而不是截断——静默改写用户的输入比拒绝更糟）。
 *
 * 导出理由同 `BOOLEAN_KEYS`：门禁要按真实取值断言「每个键都在默认设置里且上界是非负整数」。
 *
 * 上界的**值**来自 shared 的 `HISTORY_MAX_AGE_DAYS_LIMIT`，不是就地写的字面量：0.2.9 形态清理按
 * 「这个值在本版本有没有这种形态」删键，两处不同值就是两份「合法形态」的定义，而清理步那份一旦落后，
 * 用户一个合法的键会被静默删掉。
 */
export const COUNT_LIMITS: Record<string, number> = {
  historyMaxAgeDays: HISTORY_MAX_AGE_DAYS_LIMIT,
};

/**
 * 原型链上的危险键名：JSON 文本能造出自有键，展开进设置对象就会改写原型。
 *
 * 事实源放在输入闸门（判据要认得它才能把它从「陌生键」里摘出来），写面从这儿取同一份——
 * 两处各写一份清单，改了一处就会变成「一个判红一个放行」。
 */
export const UNSAFE_KEYS: readonly string[] = ["__proto__", "constructor", "prototype"];

// ---------------------------------------------------------------- 解析

/**
 * 文本 → 原始设置。坏 JSON 与非对象（数组、标量）一律得到空设置：配置文件被手改成不合法
 * 内容时读面该回落默认值，而不是让整个插件装配失败——设置坏掉不该拖垮通知。
 */
export function parseJsonObject(text: string): StoredSettings {
  try {
    const parsed: RawSettingValue = JSON.parse(text);
    return isRecord(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

// ---------------------------------------------------------------- 归一化

/**
 * 归一化：把任意输入收敛成一份完整设置，缺键补默认、非法值回落合法域——**永不失败**，
 * 是读路径的必经工序。输出是**全量**的（可选字段也写出来，空串 / 空对象表达「没有」）：
 * 让形状随输入变化会迫使下游到处判键在不在，而这里正是唯一能把这件事做掉的地方。
 */
export function normalizeConfig(input: StoredSettings): NotifyConfig {
  const fallback = DEFAULT_CONFIG;
  // 渠道形态只有 `channels` 一处输出：内置两条先物化，取值链是「条目字段 → 默认表」——**没有中间那层
  // 旧顶层键**（#1016 S3 删除）：形态演进是 upgrade 域的职责，读面不认历史。存量里的 `browserEnabled` /
  // `notifySound` 那一批由 0.2.4 的配置形态割接在装配期搬进条目并删除，读面再兜一次等于同一件事有两处实现。
  const browser = asBrowserChannel(builtinRaw(input.channels, "browser"));
  const system = asSystemChannel(builtinRaw(input.channels, "system"));
  return {
    notifyAsk: asBoolean(input.notifyAsk, fallback.notifyAsk),
    notifyQuestion: asBoolean(input.notifyQuestion, fallback.notifyQuestion),
    notifyTaskDone: asBoolean(input.notifyTaskDone, fallback.notifyTaskDone),
    notifySubagentDone: asBoolean(input.notifySubagentDone, fallback.notifySubagentDone),
    notifyTaskError: asBoolean(input.notifyTaskError, fallback.notifyTaskError),
    notifyTurnEnd: asBoolean(input.notifyTurnEnd, fallback.notifyTurnEnd),

    quietHours: asQuietHours(input.quietHours, fallback.quietHours),
    channels: [browser, system, ...outboundChannels(input.channels)],
    kindRoutes: asKindRoutes(input.kindRoutes),
    allowKinds: asStrings(input.allowKinds),

    historyMaxAgeDays: asCount(
      input.historyMaxAgeDays,
      fallback.historyMaxAgeDays,
      COUNT_LIMITS.historyMaxAgeDays,
    ),
  };
}

// ---------------------------------------------------------------- 校验

/**
 * 校验：给出首个非法键与提示。只对**显式提交**的键负责——缺键不是错误，由归一化补默认；
 * 一次只报首个非法键，因为设置页的定位光标只能落在一个字段上。**陌生键一律 400**（退役键
 * 另有逐键话术，见 RETIRED_KEYS）：写面已经不再「透传保留」陌生键，理由见 validateKnownKeys。
 */
export function validateSettings(raw: SettingsPatch): ValidationResult {
  return verdictOf(raw);
}

/**
 * 校验**合并结果**（#1016 S2 写面专用入口，本身不收紧任何判据）。
 *
 * 与 `validateSettings` **共用同一个 `verdictOf`**：判定结论逐字相同，一个字都没多判。两者
 * 唯一的差别是审谁——本函数审「这次写真正要落盘的那条」，`validateSettings` 审「客户端交上来的
 * 草稿」。存量里有越界值时两者给出相反的结论，而后者不是用户要的。
 *
 * 单列一个函数而不是给 `validateSettings` 加可选参数：那是把一个纯函数改成「视参数而定
 * 行为」的形状，调用方分不清自己拿到的是哪一种；而两条入口结论一致这件事靠的是它们**共用同一个
 * `verdictOf`**，不是靠两处同步维护。
 * （`validateSettings` 在导出面基线上——改它的签名要动基线；本条分工取的是形态上的可辩护性，
 * 不是「动了不用改基线」。）
 *
 * @param raw 提交体。
 * @param merged 写面**按字段合并后**的结论（service 域 `mergeChannels` 的产物）。它与
 *   `raw.channels` 是两份东西：前者是这次写要落盘的形态（存量没被提到的键都在里面）加上每条
 *   里「哪些字段原样来自存量」的清单，后者是客户端交上来的草稿。
 *   缺省 = 按 `raw.channels` 判（草稿测试与直调路径的旧行为，条目里每个键都算本次提交）。
 */
export function validateSettingsWithMerge(
  raw: SettingsPatch,
  merged?: MergedChannelScope,
): ValidationResult {
  return verdictOf(raw, merged);
}

/**
 * 写面「按字段合并」结论在判据侧的形状：这次写要落盘的频道数组 + 与它同下标的**两条记账**。
 *
 * 两条记账问的是两个不同的事实，故分列而不是并成一条：
 *   - `inherited`：**值**原样来自存量的字段（#1016 S2）。它让值域判据只审本次真正动过的字段。
 *   - `preexisting`：**键的缺席**本来就来自存量的必填键（见 `firstMissing`）。存量里就缺、这次也没
 *     补上的那个键。
 * 「值沿用」与「缺席沿用」合成一条会让两种判据都说不清自己为什么跳过，故各自记各自的。
 *
 * 事实源是 service 域的 `ChannelMerge`（结构同构）；缺省 `preexisting` = 没有存量可谈，草稿与直调
 * 路径因此维持原样——那里每个键都算本次提交。
 */
export type MergedChannelScope = {
  readonly channels: RawSettingValue;
  readonly inherited: readonly ReadonlySet<string>[];
  readonly preexisting?: readonly ReadonlySet<string>[];
};

/**
 * 判据本体：两条入口（草稿 / 合并结果）都走它，「两条入口给出同一份判定结论」靠这一点保证。
 *
 * 两条通道分工（#1016 S2）：`channels` 判**合并后**的条目，`inherited` 里的字段不再重判值域
 * ——它们是存量原样带回来的，重判等于让一份越界的旧配置从此存不下任何东西。其余顶层键维持整值
 * 替换：不带 `inherited` 时每个键都算本次提交。
 */
function verdictOf(raw: SettingsPatch, mergedChannels?: MergedChannelScope): ValidationResult {
  for (const [key, value] of Object.entries(raw)) {
    if (value === undefined) continue;
    // 原型链危险键不进判据：写面在落盘前整条剔除它们（writableEntries），在这里报「陌生键」只会
    // 把一次安全的写变成 400，而剔除本身已经挡住了原型改写。
    if (UNSAFE_KEYS.includes(key)) continue;
    // 走 hasOwn 而不是直接索引：constructor 这类键经 JSON 提交是可能的，直接索引会摸到
    // Object.prototype 上的同名成员，把一个陌生键误判成退役键。
    const retiredHint = Object.hasOwn(RETIRED_KEYS, key) ? RETIRED_KEYS[key] : undefined;
    if (retiredHint !== undefined) return reject(key, retiredHint);
    // 陌生键 400（#1016 S2）：写面不再透传保留，理由见 validateKnownKeys 的注释。存量里已有的
    // 陌生键不受影响——它们不在提交里，合并时原样沿用。
    if (!CONFIG_KEYS.includes(key)) return reject(key, key + " 不是已知配置键，删除它或核对拼写");
    const verdict = validateOne(key, value, key === "channels" ? mergedChannels : undefined);
    if (!verdict.ok) return verdict;
  }
  return { ok: true };
}

/**
 * 逐值相同判定：标量用 `===`，数组逐项比，对象按键集合比（**键序无关**）。
 *
 * 键序无关有实测依据：客户端把视图原样交回，JSON 往返不保证键序，而「同一份内容、
 * 键序不同」在修订号那侧已经是不算改动（见 service 侧 `stableJson` 的注释）——
 * 两处对「什么算同一份内容」必须给同一个答案，否则用户什么都没改却被判成本次改动。
 *
 * 一侧缺键即视为不同：存量的键被提交抹掉，是一次真改动（客户端的 `stripChannelEmpties`
 * 会剥掉空串可选字段，那一类确实会在下次保存时被写掉）。
 *
 * 导出给写面合并（service/impl/merge.ts）判「这次提交有没有真的改这个字段」：同一个问题——
 * 「同一份内容」——两处必须给同一个答案，各写一份迟早把「原样带回」和「用户刚改的」读反。
 */
export function sameValue(
  left: RawSettingValue | undefined,
  right: RawSettingValue | undefined,
): boolean {
  if (left === right) return true;
  // 走到这里至多一侧缺键（两侧都缺已被上一行判成相同），缺键即不同。
  if (left === undefined || right === undefined) return false;
  if (Array.isArray(left) && Array.isArray(right)) {
    if (left.length !== right.length) return false;
    return left.every((item, index) => sameValue(item, right[index]));
  }
  if (isRecord(left) && isRecord(right)) {
    const leftKeys = Object.keys(left);
    if (leftKeys.length !== Object.keys(right).length) return false;
    return leftKeys.every((key) => Object.hasOwn(right, key) && sameValue(left[key], right[key]));
  }
  return false;
}

/** 单键校验；分支与归一化的取值助手一一对应，两处判断的是同一件事。 */
function validateOne(
  key: string,
  raw: RawSettingValue,
  mergedChannels?: MergedChannelScope,
): ValidationResult {
  if (BOOLEAN_KEYS.includes(key)) return requireBoolean(key, raw);
  const limit = COUNT_LIMITS[key];
  if (Number.isFinite(limit)) return requireCount(key, raw, limit);
  if (key === "quietHours") return validateQuietHours(raw);
  if (key === "channels") return validateMergedChannels(raw, mergedChannels);
  if (key === "kindRoutes") return validateKindRoutes(raw);
  if (key === "allowKinds") return requireStringArray(key, raw);
  return { ok: true };
}

/**
 * `channels` 一支：带合并结论时审**合并结果**（写面），不带时审提交面本身（草稿与直调路径）。
 *
 * 单列而不是把三笔账摊回 `validateOne`：那处是按 key 分派的开关链，摊开之后每加一笔账就多一个可选链
 * 访问，复杂度会顶到门禁上限——而「加一笔记账」本不该是件要改判据骨架的事。
 */
function validateMergedChannels(
  raw: RawSettingValue,
  merged: MergedChannelScope | undefined,
): ValidationResult {
  return validateChannels(merged?.channels ?? raw, merged?.inherited, merged?.preexisting);
}

/** 布尔闸门键：`"true"` 之类的同义写法不算数——设置页提交的就是字面 boolean。 */
function requireBoolean(key: string, raw: RawSettingValue): ValidationResult {
  return typeof raw === "boolean" ? { ok: true } : reject(key, "需要 true 或 false");
}

/** 声音键：false = 静音、true = 默认音、字符串 = 内置音色名，三者之外都非法。 */
function requireSoundSetting(key: string, raw: RawSettingValue): ValidationResult {
  return typeof raw === "boolean" || isSoundId(raw)
    ? { ok: true }
    : reject(key, "需要 false、true 或内置音色名");
}

/** 计数键：闭区间 `[0, 上界]`，小数与越界都拒绝（截断会静默改写用户的输入）。 */
function requireCount(key: string, raw: RawSettingValue, limit: number): ValidationResult {
  const inRange = typeof raw === "number" && Number.isInteger(raw) && raw >= 0 && raw <= limit;
  return inRange ? { ok: true } : reject(key, `需要 0 到 ${limit} 之间的整数`);
}

/** 白名单字符串数组键。 */
function requireStringArray(key: string, raw: RawSettingValue): ValidationResult {
  return isStringArray(raw) ? { ok: true } : reject(key, "需要字符串数组");
}

// 免打扰校验：一次只报首错（key 恒为 quietHours，设置页的定位光标只能落在一个字段上，
// 真正指到第几行靠 hint 里的 windows[i] 下标）。旧形（带 start/end 却没有 windows）在这里 400：
// 升级步会把它们搬进 windows[0]，放行旧形等于让停留在升级前页面上的旧客户端以为保存成功了，
// 故提示直接给出刷新的出路。
function validateQuietHours(raw: RawSettingValue): ValidationResult {
  if (!isRecord(raw)) return reject("quietHours", "需要对象");
  if (typeof raw.enabled !== "boolean") return reject("quietHours", "缺少 enabled");
  if (raw.windows === undefined)
    return reject("quietHours", "缺少 windows（页面停留在升级前时，刷新后重试）");
  if (!Array.isArray(raw.windows)) return reject("quietHours", "windows 需要数组");
  if (raw.windows.length > QUIET_WINDOWS_LIMIT)
    return reject("quietHours", "windows 最多 " + QUIET_WINDOWS_LIMIT + " 个");
  const windows = validateQuietWindows(raw.windows);
  if (!windows.ok) return windows;
  if ("allowKinds" in raw && !isStringArray(raw.allowKinds))
    return reject("quietHours", "allowKinds 需要字符串数组");
  return { ok: true };
}

/** 逐条窗口校验：一次只报首错（定位光标落不到具体行，行号靠 hint 里的 windows[i]）。 */
function validateQuietWindows(windows: readonly RawSettingValue[]): ValidationResult {
  for (let index = 0; index < windows.length; index += 1) {
    const verdict = validateQuietWindow(windows[index], index);
    if (!verdict.ok) return verdict;
  }
  return { ok: true };
}

/** 单条窗口的四处判据：对象形状 / start / end / 零长。与整组形态守卫是两类判据。 */
function validateQuietWindow(item: RawSettingValue, index: number): ValidationResult {
  if (!isRecord(item)) return reject("quietHours", "windows[" + index + "] 需要对象");
  if (typeof item.start !== "string" || !isClockText(item.start))
    return reject("quietHours", "windows[" + index + "].start 需要 HH:MM");
  if (typeof item.end !== "string" || !isClockText(item.end))
    return reject("quietHours", "windows[" + index + "].end 需要 HH:MM");
  // 零长窗口写面直接拒：读面把它当未命中丢掉，而写面放行等于让用户存下一条永远不生效的时段。
  if (item.start === item.end)
    return reject(
      "quietHours",
      "windows[" + index + "].start 与 windows[" + index + "].end 不能相同",
    );
  return { ok: true };
}

/**
 * 频道数组校验：逐条 + 内置在场。
 *
 * @param inherited 与数组同下标：该条目里**沿用存量**的字段名。清单里的字段不重判值域（#1016
 *   S2 的「写面拒新增、不动存量」）；缺省 = 每个键都算本次提交。
 * @param preexisting 与数组同下标：该条目里**存量本就残缺、这次也没补上**的必填键（见 MergedChannelScope）。
 */
function validateChannels(
  raw: RawSettingValue,
  inherited?: readonly ReadonlySet<string>[],
  preexisting?: readonly ReadonlySet<string>[],
): ValidationResult {
  if (!Array.isArray(raw)) return reject("channels", "需要数组");
  for (const [index, item] of raw.entries()) {
    const verdict = validateChannel(item, inherited?.[index], preexisting?.[index]);
    if (!verdict.ok) return verdict;
  }
  // 数组级判据，排在逐条之后、内置在场之前：逐条已保证每条都过了形状判据（故这里读得到 type）。
  const unique = requireUniqueIdentities(raw);
  if (!unique.ok) return unique;
  return requireBuiltinsPresent(raw);
}

/**
 * 频道身份唯一（#1016 残留 2）。**绝对 400**：重复身份不是「界面显示重复」，而是**凭据被销毁**。
 *
 * 销毁链条（每一环都已在仓内，不是推测）：设置页对 `channels` 是**整组提交**（未整体未变时才省略）；
 * 合并的 `sameKindBase` 按**裸 id** 取首条，KEEP 分支又让其余键沿用首条的值——于是第二条的真实密钥
 * 被第一条覆盖，**每次保存毁一条凭据**，而界面上看不出任何异常。掩码还原的 `findById` 同样按裸 id
 * 查找，所以**跨类型同 id 也撞**（一条 bark 写 `id: "browser"` 会命中内置 browser 条目，连带把它的
 * 掩码还原到 bark 的键上）。
 *
 * 落点为什么是 `validateChannels` 而不是 `validateChannel`：后者是 exported、给 dry-run 逐条调用的，
 * 它**看不到数组**，重复与否在它那一层根本不是问题。数组级判据属于数组级。
 *
 * **不给 `preexisting` 放行**：放行是「存量残缺不该让一次无关保存被拒」，而重复身份是存量**自相矛盾**
 * ——同一个身份挂着两套凭据，它不是残缺。放行等于把「每次保存毁一条凭据」合法化。
 *
 * 提示必须**带下标**并**给出路**：客户端没有 id 编辑器（`chAdd` 自动分配），用户改不了 id，文案只说
 * 「重复」而不说「删掉其中一条」就等于堵死。id 不是凭据——它从不参与掩码、也不回显任何秘密——所以
 * 带进提示是安全的。
 */
function requireUniqueIdentities(list: readonly RawSettingValue[]): ValidationResult {
  const firstSeenAt = new Map<string, number>();
  for (const [index, item] of list.entries()) {
    if (!isRecord(item)) continue;
    const identity = identityOfChannel(item);
    const seenAt = firstSeenAt.get(identity);
    if (seenAt !== undefined) {
      return reject(
        "channels",
        `第 ${seenAt + 1} 条与第 ${index + 1} 条的频道身份都是 ${identity}：同一条频道只能有一个，删掉其中一条再保存`,
      );
    }
    firstSeenAt.set(identity, index);
  }
  return { ok: true };
}

/**
 * 身份口径：出站取 `id`，`id` 缺席或空串时回落 `type`（内置可以没有 `id` 键，而 `validateBuiltinChannel`
 * 规定它写了就只能是 `type`）。与 `upgrade` 域的 `identityOf` 同一式子，沿用它换来零误伤——任何现存
 * 合法配置的身份都与它一致，于是一条内置 browser 缺席 id 时不会被自己拒一次。
 */
function identityOfChannel(item: Record<string, RawSettingValue>): string {
  const type = typeof item.type === "string" ? item.type : "";
  return typeof item.id === "string" && item.id !== "" ? item.id : type;
}

/**
 * 内置频道不能删除：显式提交的 `channels` 必须仍然带着它们——这是内置频道**唯一**的特殊之处，
 * 其余一律按普通条目处理。
 *
 * 做成 400 而不是静默补回：静默补回会让「我删掉了它」与「它还在」在同一份界面上各说各话。代价是
 * 停留在升级前页面上的旧客户端（草稿里没有内置条目）会被拒一次，故提示直接给出刷新的出路。
 */
function requireBuiltinsPresent(list: readonly RawSettingValue[]): ValidationResult {
  const types = new Set<RawSettingValue>();
  for (const item of list) {
    if (isRecord(item)) types.add(item.type);
  }
  for (const type of BUILTIN_CHANNEL_TYPES) {
    if (types.has(type)) continue;
    return reject("channels", `内置渠道不能删除：缺少 ${type}（页面停留在升级前时，刷新后重试）`);
  }
  return { ok: true };
}

/** `level` 与 `preset` 是可选键：缺省各有明确语义（前者让「severity → level」映射生效，后者归一到 custom），
 * 客户端新建频道时本就不带它们——照必填拦下等于让用户的合法提交保存不了。
 *
 * 导出给草稿测试（dry-run）逐项复用：它只审单条、不审「内置必须在场」（见 requireBuiltinsPresent），
 * 草稿里可以只有目标频道一条。
 *
 * @param inherited 该条目里**沿用存量**的字段名（#1016 S2）。清单里的字段不重判值域：磁盘上
 *   一份越界的旧值不该让此后每一次无关保存都被拒——那不是用户造成的错误。缺省 = 每个键都算
 *   本次提交（草稿路径没有存量可言）。
 * @param preexisting 该条目里**存量本就残缺、这次也没补上**的必填键（#1016 S3 回归修复）。它只作用于
 *   「必填键在场」这一条形状判据，且只对清单里的键放行；缺省 = 没有存量可谈，每个键都算本次提交。 */
export function validateChannel(
  raw: RawSettingValue,
  inherited?: ReadonlySet<string>,
  preexisting?: ReadonlySet<string>,
): ValidationResult {
  if (!isRecord(raw)) return reject("channels", "频道项需要对象");
  if (raw.type === "browser" || raw.type === "system") return validateBuiltinChannel(raw, raw.type);
  if (typeof raw.id !== "string" || raw.id === "") return reject("channels", "频道缺少 id");
  if (raw.type === "bark") return validateBarkChannel(raw, raw.id, inherited, preexisting);
  if (raw.type === "webhook") return validateWebhookChannel(raw, raw.id, inherited, preexisting);
  return reject("channels", "频道 type 需要 bark、webhook、browser 或 system");
}

/** 内置频道：身份由 `type` 唯一确定（`id` 只是回显，写了就必须一致），开关与声音逐个按各自值域校验。
 *
 * 这几个键**不按 inherited 跳过**：内置条目的字段集是固定的五六个，0.2.9 形态清理会把缺席字段
 * 补齐，客户端也就每次都原样带回——存量里出现非布尔只可能是有人手改过文件（清理只在刻度推进时跑
 * 一次，救不了「升级后手改」），而那正是要拒的。 */
function validateBuiltinChannel(
  raw: Record<string, RawSettingValue>,
  type: BuiltinChannelType,
): ValidationResult {
  if (raw.id !== undefined && raw.id !== type)
    return reject("channels", `内置频道 ${type} 的 id 只能是 ${type}`);
  for (const key of ["enabled", "popup", "whenVisible"]) {
    if (raw[key] === undefined || typeof raw[key] === "boolean") continue;
    return reject("channels", `内置频道 ${type} 的 ${key} 需要 true 或 false`);
  }
  return raw.sound === undefined ? { ok: true } : requireSoundSetting("channels", raw.sound);
}

/** bark 频道：`baseUrl` 与 `deviceKey` 是投递必需（清单见 shared 的 REQUIRED_KEYS.bark）；
 * `level` 缺省时让 severity 映射生效，故可省。
 *
 * 必填键在**合并后**的条目上判：客户端可以只提交它改的那一个字段，其余从存量沿用。 */
function validateBarkChannel(
  raw: Record<string, RawSettingValue>,
  id: string,
  inherited?: ReadonlySet<string>,
  preexisting?: ReadonlySet<string>,
): ValidationResult {
  const missing = firstMissing(raw, REQUIRED_KEYS.bark, preexisting);
  if (missing !== undefined) return reject("channels", `bark 频道 ${id} 缺少 ${missing}`);
  if (isEdited(inherited, "level") && raw.level !== undefined && !isMember(raw.level, BARK_LEVELS))
    return reject("channels", `bark 频道 ${id} 的 level 非法`);
  if (
    isEdited(inherited, "levels") &&
    isRecord(raw.levels) &&
    Object.keys(raw.levels).length > BARK_LEVELS_LIMIT
  ) {
    return reject("channels", `bark 频道 ${id} 的 levels 最多 ${BARK_LEVELS_LIMIT} 项`);
  }
  return validateKnownKeys(raw, id, inherited, BARK_KNOWN_KEYS, BARK_RESERVED_KEYS, "bark");
}

/** webhook 频道：`url` 与 `auth` 是投递必需；`preset` 缺省归一到 custom，故可省。
 *
 * `auth` 的判据是**取值域**（缺席与非法同一句话），故不按 inherited 跳过：客户端的草稿来自读面
 * 归一化，永远带得出一个合法值，存量里出现非法 auth 只可能是手改过文件。 */
function validateWebhookChannel(
  raw: Record<string, RawSettingValue>,
  id: string,
  inherited?: ReadonlySet<string>,
  preexisting?: ReadonlySet<string>,
): ValidationResult {
  const missing = firstMissing(raw, REQUIRED_KEYS.webhook, preexisting);
  if (missing !== undefined) return reject("channels", `webhook 频道 ${id} 缺少 ${missing}`);
  if (!isMember(raw.auth, WEBHOOK_AUTHS))
    return reject("channels", `webhook 频道 ${id} 的 auth 非法`);
  if (
    isEdited(inherited, "preset") &&
    raw.preset !== undefined &&
    !isMember(raw.preset, WEBHOOK_PRESETS)
  )
    return reject("channels", `webhook 频道 ${id} 的 preset 非法`);
  if (
    isEdited(inherited, "template") &&
    typeof raw.template === "string" &&
    raw.template.length > WEBHOOK_TEMPLATE_MAX_CHARS
  ) {
    return reject(
      "channels",
      `webhook 频道 ${id} 的 template 最多 ${WEBHOOK_TEMPLATE_MAX_CHARS} 字符`,
    );
  }
  return validateKnownKeys(
    raw,
    id,
    inherited,
    WEBHOOK_KNOWN_KEYS,
    WEBHOOK_RESERVED_KEYS,
    "webhook",
  );
}

/**
 * 频道条目里的陌生键：一律 400（#1016 S2 删掉了 extras 概念）。
 *
 * 为什么不再「透传保留」：透传面要求读面把陌生键收进 `extras` 子对象再原样交回客户端，而写面
 * 只放行 string/number——于是 `extras` 这个**对象**自己撞上那条判据，该频道所在配置从此再也
 * 保存不了（#1016 缺陷 B）。收窄到「本版本认识的键」把那条自撞的口子关掉：写面拒新增，磁盘上
 * **已有**的陌生键由合并原样沿用（它不在提交里），既不丢也不锁人。
 *
 * 保留键（凭据别名）与其它陌生键**分两句**：前者是「你写的是别名，合法凭据只能走已知字段」，
 * 后者是「这个键从来不是本包的字段」——两者的排查方向不同，共用一句会把人引到错误的原因上。
 *
 * @param inherited 沿用存量的字段名；清单里的键不判（存量里的陌生键不该被一次无关保存追责）。
 */
function validateKnownKeys(
  raw: Record<string, RawSettingValue>,
  id: string,
  inherited: ReadonlySet<string> | undefined,
  known: readonly string[],
  reserved: readonly string[],
  kindLabel: string,
): ValidationResult {
  for (const key of Object.keys(raw)) {
    if (known.includes(key)) continue;
    if (!isEdited(inherited, key)) continue;
    if (reserved.includes(key))
      return reject("channels", `${kindLabel} 频道 ${id} 的 ${key} 是保留键：凭据只能走已知字段`);
    return reject("channels", `${kindLabel} 频道 ${id} 的 ${key} 不是已知键：删除它或核对拼写`);
  }
  return { ok: true };
}

function validateKindRoutes(raw: RawSettingValue): ValidationResult {
  if (!isRecord(raw)) return reject("kindRoutes", "需要对象");
  for (const key of Object.keys(raw)) {
    const value = raw[key];
    if (!Array.isArray(value) || !value.every((item) => typeof item === "string")) {
      return reject("kindRoutes", `${key} 需要字符串数组`);
    }
  }
  return { ok: true };
}

function reject(key: string, hint: string): ValidationResult {
  return { ok: false, error: { key, hint } };
}

// ---------------------------------------------------------------- 净化

/**
 * 净化：只保留契约认识的键。陌生键一律剔除而不是拒绝——配置文件是共享的，别的东西写进来的
 * 键不该让设置读取失败，也不该被原样带进用户层再写回去。**不归一化**：净化只回答「这个键归
 * 不归我」，在这里顺手归一化会让写路径把用户的原始提交偷偷改写掉。
 *
 * @returns 净化后的部分设置；输入不是对象时得到空设置——「一个键都不认识」与「没有键」对
 *   调用方是同一件事，不必再给一个空值语义让它自己判。
 */
export function sanitizeSettings(raw: StoredSettings): Partial<NotifyConfig> {
  const kept: Record<string, RawSettingValue> = {};
  if (!isRecord(raw)) return kept;
  for (const key of CONFIG_KEYS) {
    const value = raw[key];
    if (value === undefined) continue;
    kept[key] = value;
  }
  return kept as Partial<NotifyConfig>;
}

// ---------------------------------------------------------------- 取值助手

/** 原始值是不是一个 JSON 对象（数组与空值不算）。 */
function isRecord(raw: RawSettingValue): raw is Record<string, RawSettingValue> {
  return typeof raw === "object" && raw !== null && !Array.isArray(raw);
}

/**
 * 该字段是否算「本次提交」：没有存量基线时一律算（草稿与直调路径），有则跳过沿用存量的字段。
 *
 * 这是 #1016 S2「写面拒新增、不动存量」的执行点：值域与尺寸判据只审本次真正动过的字段，磁盘上
 * 一份越界的旧值不该让此后每一次无关保存都被拒。形状判据（必填键、内置在场）**不看这个**——它问的
 * 不是「值是不是本次改的」而是「这个键在不在」，两者问的不是同一件事。
 *
 * 「存量本就残缺的必填键」也**不看这个**、而是看另一笔 `preexisting` 账：`inherited` 记的是「值原样
 * 来自存量」，而一个从未存在过的键没有值可沿用。两笔账分开记，各自只对自己的那族判据负责。
 */
function isEdited(inherited: ReadonlySet<string> | undefined, field: string): boolean {
  return inherited === undefined || !inherited.has(field);
}

/** 命中白名单则保留，其余（含缺键）回落。 */
function isMember<T extends string>(raw: RawSettingValue, allowed: readonly T[]): raw is T {
  return typeof raw === "string" && allowed.some((item) => item === raw);
}

/**
 * 「这个必填键交上来了没有」：**非空串**才算交上来。事实源是 `REQUIRED_KEYS`（S1 的共享 schema），
 * 「在场」是这一族判据共用的那一句，故单列并导出给写面合并用：两处各写一份「在场」，迟早在
 * 「空串算不算在场」上漂。
 *
 * 这一族的另两处：读面 `asChannel` 的空壳判定（`asBarkChannel` 对空串必填键返回 `ok: false`）与
 * upgrade 域 0.2.9 形态清理的**必填键判据**（canonical-keys 的 `requiredKeysOf`）。后者的必填键
 * **清单**同样只从 `REQUIRED_KEYS` 读，不再在本域另抄一份。
 */
export function isDeliveredRequired(value: RawSettingValue | undefined): boolean {
  return typeof value === "string" && value !== "";
}

/**
 * 必填键里第一个**这次写该负责**的缺项，全都在（或缺的都早已残缺）则 undefined。
 *
 * 按清单序返回**第一个**缺项而不是逐条拒：话术里带的是键名，缺哪个就报哪个，两项皆缺时报前一个
 * ——与逐条 if 链给出的结论完全一致（同一顺序、同一判据）。
 *
 * `preexisting` 里那些键**不计入缺项**，这是 #1016 S3 的一处回归修复：读面自 S3 起不丢弃半坏条目
 * （视图逐字外发），而这条判据原本是**绝对**的（只看合并后的条目），于是「用户在升级之后手改文件造出
 * 一条半坏条目」之后，此后每一次保存都 400——连改**别的**频道的名字都存不下去，比 S3 之前更差。
 *
 * 放行的条件是「两边都坏」：存量里这个键本来就是坏的（`preexisting` 由 merge 依存量事实算出），
 * 且这次写既没补上也没删它。**显式的删除手势不在此列**——它由 merge 的第三态在判据之前就 400 拒掉
 * （「必填键，不能删除」），所以「删掉一个必填键」的后果仍然一律被拒，只是拒在更早、更准的那一步。
 *
 * 反过来，存量里这个键是好的、这次被写成非法值（数字 / 对象 / 空串），`preexisting` 不含它，照样 400。
 * 换句话说：这条判据问的是「这次写有没有把事情做坏」，不是「磁盘上这份配置现在完不完整」——后者归
 * 读面（投递投影丢弃空壳）与 upgrade 域的形态清理，不归写面。
 */
function firstMissing(
  raw: Record<string, RawSettingValue>,
  keys: readonly string[],
  preexisting?: ReadonlySet<string>,
): string | undefined {
  for (const key of keys) {
    if (preexisting?.has(key) === true) continue;
    if (!isDeliveredRequired(raw[key])) return key;
  }
  return undefined;
}

/** 字符串数组：元素逐个看，非字符串即不算（与归一化侧「剔除非字符串项」是同一口径的两面）。 */
function isStringArray(raw: RawSettingValue): boolean {
  return Array.isArray(raw) && raw.every((item) => typeof item === "string");
}

function asBoolean(raw: RawSettingValue, fallback: boolean): boolean {
  return typeof raw === "boolean" ? raw : fallback;
}

function asString(raw: RawSettingValue, fallback: string): string {
  return typeof raw === "string" ? raw : fallback;
}

/** 非负整数且不越界；越界回落而不是截断（与校验的口径一致：拒绝胜过静默改写）。 */
function asCount(raw: RawSettingValue, fallback: number, limit: number): number {
  return typeof raw === "number" && Number.isInteger(raw) && raw >= 0 && raw <= limit
    ? raw
    : fallback;
}

/** 声音设置：`false` / `true` / 内置音色名三种形态；音色名非法即回落。 */
function asSound(raw: RawSettingValue, fallback: SoundSetting): SoundSetting {
  if (typeof raw === "boolean") return raw;
  return isSoundId(raw) ? raw : fallback;
}

/** 字符串数组：非字符串项剔除而不是整组丢弃（一项脏值不该连累其余）。 */
function asStrings(raw: RawSettingValue): string[] {
  return Array.isArray(raw) ? raw.filter((item): item is string => typeof item === "string") : [];
}

// 免打扰归一化：永不失败。单项非法（格式错、零长）只废该项，不废整组；全废则等于未命中
// （沿用「脏设置不吃掉所有通知」）。`windows` 缺席或非数组一律给 []（空数组 = 未命中）——#1016 S3
// 删掉了读面的旧 start/end 回落，那条链由 upgrade 域 0.2.6 的割接负责。显式 [] 同样保持 []。
function asQuietHours(raw: RawSettingValue, fallback: QuietHoursConfig): QuietHoursConfig {
  // 回落交出深副本：默认表是共享的，调用方就地改写它会污染此后每一个读者（windows 是数组，
  // 浅拷贝仍与默认表共享同一份列表）。
  if (!isRecord(raw)) return copyQuietHours(fallback);
  const enabled = asBoolean(raw.enabled, fallback.enabled);
  const allowKinds = asStrings(raw.allowKinds);
  // `windows` 缺席即「没有时段」，**不回落旧 start/end、不回落默认表**（#1016 S3 删除读面历史兼容）：
  // 旧形由 0.2.6 的免打扰多时间窗割接在装配期搬进 `windows[0]` 并删旧键，读面再兜一次就等于同一件事
  // 有两处实现，而两处迟早对「半截旧形」给出不同答案。回落方向是「丢键」而不是「落默认值」：
  // 用户显式写了 `quietHours` 却没有 `windows`，那表达的就是一条时段都不命中。
  if (!Array.isArray(raw.windows)) {
    return { enabled: enabled, windows: [], allowKinds: allowKinds };
  }
  const windows: QuietWindow[] = [];
  for (const item of raw.windows) {
    const window = asQuietWindow(item);
    if (window !== null) windows.push(window);
  }
  return { enabled: enabled, windows: windows, allowKinds: allowKinds };
}

// 默认表的免打扰深副本。
function copyQuietHours(fallback: QuietHoursConfig): QuietHoursConfig {
  const copied: QuietHoursConfig = {
    enabled: fallback.enabled,
    windows: fallback.windows.map((window) => ({ ...window })),
  };
  if (fallback.allowKinds !== undefined) copied.allowKinds = [...fallback.allowKinds];
  return copied;
}

// 单个窗口的读面收窄；非法与零长一律丢项（返回 null），不连累同组的其余项。
function asQuietWindow(raw: RawSettingValue): QuietWindow | null {
  if (!isRecord(raw)) return null;
  if (typeof raw.start !== "string" || !isClockText(raw.start)) return null;
  if (typeof raw.end !== "string" || !isClockText(raw.end)) return null;
  if (raw.start === raw.end) return null;
  return { start: raw.start, end: raw.end };
}

/** kind → 频道 id 的稀疏路由；值不是数组的项剔除。 */
function asKindRoutes(raw: RawSettingValue): Record<string, string[]> {
  const routes: Record<string, string[]> = {};
  if (!isRecord(raw)) return routes;
  for (const key of Object.keys(raw)) {
    routes[key] = asStrings(raw[key]);
  }
  return routes;
}

/** 频道数组的逐项读取结果；认不出的项不带回值。 */
type ChannelRead = { ok: true; channel: ChannelConfig } | { ok: false };

/**
 * 出站实例数组：逐项归一化，**认不出的项直接丢弃**——一个没写 id、没写 url、没写凭据的「频道」
 * 没有任何可投递的目标，补成空壳只会在投递时制造一次必然失败的尝试。
 *
 * **这一次丢弃是 upgrade 域 0.2.9 形态清理的承重前提**（#1016 P1-2 选 (a)）：那一步不再删「必填键
 * 空串或缺席」的半坏条目，理由正是这里把它们整条剔出投递投影——留在磁盘上不等于会被打出去。
 * 两边要一起读；单独动任一侧的症状写在 canonical-keys.ts 文件头的「第三条路」那段。
 *
 * 内置条目在这里被跳过：它们由 `asBrowserChannel` / `asSystemChannel` 单独物化，且恒排在最前。
 */
function outboundChannels(raw: RawSettingValue): ChannelConfig[] {
  const channels: ChannelConfig[] = [];
  if (!Array.isArray(raw)) return channels;
  // 按身份取**首项**（#1016 残留 2）。写面已绝对拒重复身份，故能从磁盘读到重复的只有两种来源：手改过
  // 文件，或 0.2.9 之前的存量。此处两条都投 = 一次通知发两遍。
  //
  // **不是「四处同一口径」**（此前的注释这么写，不实）：这里用的是 `id || type` 按**数组序**取首条；
  // 掩码还原 `findById` 与合并 `indexById` 是另一把尺——**只按裸 id**，没有非空 id 的条目根本不进
  // 索引；`builtinRaw` 是第三把——**只按 type**，完全无视 id。三把尺只在「内置条目都带 id、用户条目
  // 都带唯一 id」这一种常见形态下碰巧同形，其余形态各说各话。
  //
  // **已知取舍（B / C 两个形状，登记在实现笔记的「已知缺口」段）**：`seen.add` 在 `asChannel` 之前，
  // 于是**半坏条目（`baseUrl:""` / `deviceKey:""`）会先占掉身份**，把后面一条健康的同 `id` 条目挤出
  // 投递池；跨类型重复时则是「数组里靠前的那条」赢，落选那条**从此不再投递**。两种形状都以「重复
  // 身份」为前提——写面已绝对 400、客户端 `chAdd` 生成的 id 恒为 `bark-N` 且自带去重，故 UI 造不出
  // 这种配置，只剩手改文件与 0.2.9 之前的存量。**本轮刻意不动这个位置**：把 `seen.add` 挪到
  // `asChannel` 之后会让跨类型重复从 0 条变 1 条（让用户那条 bark 赢过内置条目），那是另一套语义、
  // 需要单独决策；登记为缺口比顺手改对更诚实。
  const seen = new Set<string>();
  for (const item of raw) {
    if (isRecord(item)) {
      const identity = identityOfChannel(item);
      if (seen.has(identity)) continue;
      seen.add(identity);
    }
    const read = asChannel(item);
    if (read.ok) channels.push(read.channel);
  }
  return channels;
}

/** 输入数组里首个指定类型的内置条目（原始形态）；同类型的后来者被丢弃——内置身份由 `type` 唯一确定。 */
function builtinRaw(
  raw: RawSettingValue,
  type: BuiltinChannelType,
): Record<string, RawSettingValue> | undefined {
  if (!Array.isArray(raw)) return undefined;
  for (const item of raw) {
    if (isRecord(item) && item.type === type) return item;
  }
  return undefined;
}

/**
 * 浏览器频道物化：条目字段 → 默认表。
 *
 * **只认条目**（#1016 S3 删除读面历史兼容）：取值链上不再有「存量投影键（0.2.3 的顶层键）」那一层。
 * 0.2.3 的 `browserEnabled` / `browserNotify` / `browserSound` / `notifyWhenVisible` 与更早的全局
 * `notifySound` 都由 upgrade 域的 0.2.4 配置形态割接在装配期搬进本条目并删除旧键；读面再兜一次，
 * 两处实现对「只搬了一半的文件」迟早给出不同答案，而那时已经没有任何用户能看出来是哪一处错了。
 */
function asBrowserChannel(raw: Record<string, RawSettingValue> | undefined): BrowserChannelConfig {
  const fallback = builtinDefault("browser");
  const source: Record<string, RawSettingValue> = raw ?? {};
  return {
    type: "browser",
    id: "browser",
    enabled: asBoolean(source.enabled, fallback.enabled),
    popup: asBoolean(source.popup, fallback.popup),
    sound: asSound(source.sound, fallback.sound),
    whenVisible: asBoolean(source.whenVisible, fallback.whenVisible),
  };
}

/** 系统频道物化：链与浏览器频道同构，只是没有 `whenVisible`——那是浏览器出口独有的展示条件。 */
function asSystemChannel(raw: Record<string, RawSettingValue> | undefined): SystemChannelConfig {
  const fallback = builtinDefault("system");
  const source: Record<string, RawSettingValue> = raw ?? {};
  return {
    type: "system",
    id: "system",
    enabled: asBoolean(source.enabled, fallback.enabled),
    popup: asBoolean(source.popup, fallback.popup),
    sound: asSound(source.sound, fallback.sound),
  };
}

/**
 * 默认表里的内置条目：物化的最后一级回落。
 *
 * 断言只为把「按 type 找到的那条」收窄成对应型号——查找条件就是 type 相等。默认表是本模块的常量，
 * 两条内置条目必然在场；真缺了当场抛错比静默降级好（那是编码错误，不是用户输入的问题）。
 */
function builtinDefault<T extends BuiltinChannelType>(
  type: T,
): Extract<ChannelConfig, { type: T }> {
  for (const channel of DEFAULT_CONFIG.channels) {
    if (channel.type === type) return channel as Extract<ChannelConfig, { type: T }>;
  }
  throw new Error(`dsh-notifier: 默认设置里缺少内置频道 ${type}`);
}

function asChannel(raw: RawSettingValue): ChannelRead {
  if (!isRecord(raw)) return { ok: false };
  const id = asString(raw.id, "");
  if (id === "") return { ok: false };
  if (raw.type === "bark") return asBarkChannel(raw, id);
  if (raw.type === "webhook") return asWebhookChannel(raw, id);
  return { ok: false };
}

function asBarkChannel(raw: Record<string, RawSettingValue>, id: string): ChannelRead {
  const baseUrl = asString(raw.baseUrl, "");
  const deviceKey = asString(raw.deviceKey, "");
  if (baseUrl === "" || deviceKey === "") return { ok: false };
  const channel: BarkChannelConfig = {
    type: "bark",
    id,
    enabled: asBoolean(raw.enabled, false),
    name: asString(raw.name, ""),
    baseUrl,
    deviceKey,
    group: asString(raw.group, ""),
    sound: asString(raw.sound, ""),
    icon: asString(raw.icon, ""),
    url: asString(raw.url, ""),
    timeoutMs: asCount(raw.timeoutMs, 0, BARK_TIMEOUT_MS_LIMIT),
    levels: asLevels(raw.levels),
  };
  // 紧急度不兜底：缺了它才轮到「severity → level」那层映射，兜成 active 会让 error 通知
  // 永远发不出 timeSensitive；徽标同理，0 是有意义的取值。
  if (isMember(raw.level, BARK_LEVELS)) channel.level = raw.level;
  if (typeof raw.badge === "number") channel.badge = raw.badge;
  return { ok: true, channel };
}

function asLevels(raw: RawSettingValue): Record<string, BarkLevel> {
  const levels: Record<string, BarkLevel> = {};
  if (!isRecord(raw)) return levels;
  for (const key of Object.keys(raw)) {
    const value = raw[key];
    if (isMember(value, BARK_LEVELS)) levels[key] = value;
  }
  return levels;
}

function asWebhookChannel(raw: Record<string, RawSettingValue>, id: string): ChannelRead {
  const url = asString(raw.url, "");
  if (url === "") return { ok: false };
  const channel: WebhookChannelConfig = {
    type: "webhook",
    id,
    enabled: asBoolean(raw.enabled, false),
    name: asString(raw.name, ""),
    url,
    preset: isMember(raw.preset, WEBHOOK_PRESETS) ? raw.preset : "custom",
    auth: isMember(raw.auth, WEBHOOK_AUTHS) ? raw.auth : "none",
    token: asString(raw.token, ""),
    username: asString(raw.username, ""),
    password: asString(raw.password, ""),
    headerName: asString(raw.headerName, ""),
    headerValue: asString(raw.headerValue, ""),
    template: asString(raw.template, ""),
    headers: asHeaders(raw.headers),
    timeoutSec: asCount(raw.timeoutSec, 0, 600),
  };
  return { ok: true, channel };
}

function asHeaders(raw: RawSettingValue): Record<string, string> {
  const headers: Record<string, string> = {};
  if (!isRecord(raw)) return headers;
  for (const key of Object.keys(raw)) {
    const value = raw[key];
    if (typeof value === "string") headers[key] = value;
  }
  return headers;
}

/**
 * config 域凭据的掩码往返（安全模块）：**读出去一律掩码，写回来按 id 还原**——没有这条对称，凭据只有两种结局：
 * 明文出到界面与日志，或被掩码覆盖成字面量。密钥字段清单在 src/shared/config-schema.ts
 * （`CHANNEL_SECRET_FIELDS`），是唯一扩展点，两处各写一份清单一定会漂移。
 */
import { CHANNEL_SECRET_FIELDS } from "../../../../shared/interface.ts";
import type { ChannelType } from "../../../../shared/interface.ts";
import type {
  ChannelConfig,
  NotifyConfig,
  RawSettingValue,
  StoredSettings,
} from "../model/type.ts";

/** 掩码占位：提交整值等于它 = 该字段「未修改」。 */
const SECRET_MASK = "********";

/** 掩码还原结果：成功带回还原后的频道数组；失败 = 有实例提交了掩码却无原值。 */
type UnmaskResult = { ok: true; channels: RawSettingValue } | { ok: false };

/** 单项还原结果；失败即「没有原值可还原」，整批随之中止。 */
type UnmaskedChannel = { ok: true; channel: RawSettingValue } | { ok: false };

// 各频道类型的密钥字段清单在 src/shared/config-schema.ts（两端共享面）：它是掩码往返的唯一
// 扩展点，两处各写一份清单一定会漂移，症状是凭据明文出到界面或被掩码覆盖成字面量。本域只消费。
// 键集由本域的类型面复核：新增频道类型而共享表漏登记，赋值处即编译失败。
const SECRET_FIELDS: Record<ChannelType, readonly string[]> = CHANNEL_SECRET_FIELDS;

/** 读出口脱敏：深拷贝后把密钥字段掩码。拷贝而非原地改，是因为它作用于**即将外发的视图**，而同一份设置在域内还要以
 * 明文参与投递；频道项按**原始值**处理——存储层不受契约约束，里面可能躺着更高版本写的频道类型。 */
export function redactConfig(value: Partial<NotifyConfig>): Partial<NotifyConfig> {
  const copy = structuredClone(value);
  const channels = copy.channels;
  if (!Array.isArray(channels)) return copy;
  // 断言只声明"这是同一批频道，只是密钥被换成了掩码"——掩码不会改变项的形状。
  copy.channels = channels.map(maskChannel) as ChannelConfig[];
  return copy;
}

/**
 * 存储层的读出口脱敏：视图的 `user` 要**原样带陌生键**（只掩码凭据），所以不能先过净化——
 * 净化会把用户手写的未来键从视图里摘掉，而它们其实还在文件里，界面与文件就此各说各话。
 */
export function redactStored(stored: StoredSettings): StoredSettings {
  const masked: Record<string, RawSettingValue> = {};
  for (const [key, value] of Object.entries(stored)) {
    masked[key] =
      key === "channels" && Array.isArray(value)
        ? (value.map(maskChannel) as RawSettingValue)
        : structuredClone(value);
  }
  return masked;
}

/**
 * 写入口还原：patch 里等于掩码的字段，按 **id** 对齐取回原值——按下标对齐时数组顺序一变，
 * 就会把 A 实例的凭据回填进 B。
 *
 * @param patchChannels 提交上来的频道数组。
 * @param userChannels 已存储的频道数组（原值来源）；缺省视为没有原值。
 * @returns 还原后的频道数组；`ok: false` = 有实例提交了掩码却没有对应原值，调用方应当拒绝
 *   ——掩码只能表达「未修改」，不能凭空造出一个凭据。
 */
export function unmaskChannels(
  patchChannels: RawSettingValue,
  userChannels?: RawSettingValue,
): UnmaskResult {
  if (!Array.isArray(patchChannels)) return { ok: false };
  const existing: readonly RawSettingValue[] = Array.isArray(userChannels) ? userChannels : [];
  const restored: RawSettingValue[] = [];
  for (const item of patchChannels) {
    const read = unmaskChannel(item, existing);
    if (!read.ok) return { ok: false };
    restored.push(read.channel);
  }
  return { ok: true, channels: restored };
}

function maskChannel(channel: RawSettingValue): RawSettingValue {
  if (!isRecord(channel)) return channel;
  const masked: Record<string, RawSettingValue> = { ...channel };
  for (const field of secretFieldsOfType(channel.type)) {
    // 只掩**非空串**：空串在这份配置里的含义是「未设置」而不是「一个内容为空的凭据」——读面
    // 把磁盘上缺席的密钥补成空串（input 的 asString 兜底），用户新建的频道三个密钥键本来就全无。
    // 把它掩成占位，占位便绕过了客户端的空串剥除（值不是空串，剥不掉）原样回到写面；还原侧按
    // id 取回的是 undefined（磁盘上并没有这个键），遂拒掉整批 400——用户只切一下 enabled 开关
    // 就再也存不下去。非空串照旧掩码：脱敏的口子不能借这次放宽一并打开。
    if (typeof masked[field] === "string" && masked[field] !== "") masked[field] = SECRET_MASK;
  }
  return masked;
}

function unmaskChannel(
  patch: RawSettingValue,
  existing: readonly RawSettingValue[],
): UnmaskedChannel {
  if (!isRecord(patch)) return { ok: true, channel: patch };
  const masked = secretFieldsOf(patch);
  if (masked.length === 0) return { ok: true, channel: patch };

  const original = findById(existing, idOf(patch));
  if (!original.ok) return { ok: false };

  const restored: Record<string, RawSettingValue> = { ...patch };
  for (const field of masked) {
    const value = original.channel[field];
    if (typeof value !== "string") return { ok: false };
    restored[field] = value;
  }
  return { ok: true, channel: restored };
}

/**
 * 某个频道类型的密钥字段；**不认识的类型给空清单**——配置文件里可能躺着更高版本或手写进去的
 * 频道，读出口的职责是原样送出而不是报错：在这里抛，用户看到的是设置页整页 500，而真正的原因
 * （某个陌生频道类型）没有任何线索指向它。
 */
function secretFieldsOfType(type: RawSettingValue): readonly string[] {
  if (type === "bark" || type === "webhook") return SECRET_FIELDS[type];
  return [];
}

/** 提交项里**实际带了掩码**的密钥字段；不是频道对象时为空。 */
function secretFieldsOf(patch: Record<string, RawSettingValue>): readonly string[] {
  return secretFieldsOfType(patch.type).filter((field) => patch[field] === SECRET_MASK);
}

/**
 * 还原后是否还残留掩码字面量（跨 type 残留 / 改名残留）：还原只处理「当前 type 的密钥字段」，
 * `bark → webhook` 后残留的 `deviceKey: "********"` 这类字面量不会被还原——把它当真实凭据
 * 发出去等于把占位符写进对端日志，静默剥离等于替用户改配置，两条路都不对，由调用方整体拒绝。
 *
 * 扫的是**全部已知类型的密钥字段**而不只是当前 type 的：残留恰恰发生在「字段不属于当前
 * type」时，只扫当前 type 永远扫不到它。未知类型的密钥字段不在表里，扫不到——那种频道连
 * 校验都过不了，到不了这一步。
 */
export function hasResidualMask(channel: RawSettingValue): boolean {
  if (!isRecord(channel)) return false;
  for (const fields of Object.values(SECRET_FIELDS)) {
    for (const field of fields) {
      if (channel[field] === SECRET_MASK) return true;
    }
  }
  return false;
}

/** 按 id 查找的结果；找不到时不带回任何值。 */
type LookupResult = { ok: true; channel: Record<string, RawSettingValue> } | { ok: false };

/** 按 id 找已存储的同名频道；id 为空或找不到时给不出原值。 */
function findById(existing: readonly RawSettingValue[], id: string): LookupResult {
  if (id === "") return { ok: false };
  for (const item of existing) {
    if (isRecord(item) && item.id === id) return { ok: true, channel: item };
  }
  return { ok: false };
}

function idOf(patch: Record<string, RawSettingValue>): string {
  const id = patch.id;
  return typeof id === "string" ? id : "";
}

function isRecord(raw: RawSettingValue): raw is Record<string, RawSettingValue> {
  return typeof raw === "object" && raw !== null && !Array.isArray(raw);
}

/**
 * dsh-notifier config 域 —— 写面的**按字段合并**（#1016 重构第 3 步）。
 *
 * 为什么不再整组替换：`channels` 过去是「提交的那份整个盖上去」，于是**客户端没在 patch 里带的
 * 字段，落盘后就没了**。它与「键缺席 = 不动」的语义正面冲突，也是 #1016 三条既有缺陷的共同根因。
 * 本模块把一个频道条目拆回**逐字段**的决策，每态都只回答一件事：这次提交对这个字段做了什么。
 *
 * 五态（键缺席之外的四态按判据顺序求值）：
 *   1. 键**缺席**（提交里没这个键）  -> 不动，沿用存量值（且该字段本次**不重新判合法性**）
 *   2. 值 == 掩码字面量 `"********"` -> **按该键是不是密钥字段分三段**（判据见 `fieldVerdict`）：
 *      本 type 密钥字段沿用存量值、无源 400；别的 type 的密钥字段名 400（跨 type 残留）；
 *      非密钥键是普通值，照写
 *   3. 值 == `null`                    -> 删键（显式删除：客户端把「清空」表达成这个手势）
 *   4. 值 == `""` 且该键非必填         -> 删键（与 null 同义，为旧客户端兜底）
 *   5. 其它值                          -> 写入
 *
 * 外加四条硬规则（都在**删键之前**判，因为「删掉一个必填键」要 400 而不是静默降级成一个空壳）：
 *   - 必填键传 `null` 或 `""` -> 400，话术指向「必填键，不能删除」；「必填键」含**取值域类**
 *     必填键（webhook 的 `auth`），两张表的合集见 `requiredKeysOf`——判据在输入闸门，处置在本模块；
 *   - 掩码落在密钥字段上而**无原值可还原**（状态 2 的前半）-> 400，话术是
 *     `NEW_CHANNEL_MASK_HINT`，与草稿测试（dry-run）同一句：两条链路对同一份草稿不许给出两个答案；
 *   - 掩码落在**别的 type 的密钥字段名**上（状态 2 的后半，跨 type 残留）-> 400，话术是
 *     `RESIDUAL_MASK_HINT`，同样与 dry-run 同一句；
 *   - 删键之后由调用方**重新校验合并结果**：必填键此刻为空 -> 400（validateChannel 的既有判据）。
 *
 * 本模块**不判值域**（枚举白名单、尺寸上限、陌生键）——那些是输入闸门的事，调用方拿合并结果去
 * 问它。合并只回答「这次写把什么变成了什么」。
 */
import {
  CHANNEL_SECRET_FIELDS,
  REQUIRED_KEYS,
  VALUE_DOMAIN_REQUIRED_KEYS,
} from "../../../../shared/interface.ts";
import { isDeliveredRequired, sameValue } from "../input/index.ts";
import type { RawSettingValue, SettingInvalid } from "../model/type.ts";

/** 掩码占位字面量：与 redact 域、设置页同一份跨端契约。
 *
 * 独立写出而不从 redact 域导入，与 service.test.ts 的同一纪律一致：它是**跨端契约**（客户端也
 * 按这个字面量原样带回），把它变成一条 import 会让「两端口径一致」这件事从「两边各写一份、互相
 * 校对」退化成「谁忘了同步就静默漂」。 */
const SECRET_MASK = "********";

/** 身份键：删掉它们条目就不再是同一条频道，与投递必需键同等对待。 */
const IDENTITY_KEYS: readonly string[] = ["id", "type"];

/**
 * 掩码无原值可还原时的拒绝理由（掩码只表达「未修改」，没有原值可还原时它什么也不是）。
 *
 * **写面与草稿测试（dry-run）共用这一句**：id 改名带掩码、无源新频道带掩码是同一种失败，两条链路
 * 各写一句迟早漂成两种说法——而「同一份草稿在保存与试发两条路上得到两个答案」正是「掩码搬进
 * merge」要消灭的那个缺陷。
 *
 * 事实源放在**写面**这一侧而不是 redact 域：dry-run 已经从这里 import（见 draft/index.ts），
 * 两句 hints 因此只有一份字面量，跨链路漂移在编译期就不可能发生。 */
export const NEW_CHANNEL_MASK_HINT = "新增频道不能提交掩码占位，请填写真实凭据";

/**
 * 掩码落在**别的 type 的密钥字段名**上时的拒绝理由（跨 type 残留：bark→webhook 后剩一个
 * `deviceKey: "********"`）。
 *
 * 与 `NEW_CHANNEL_MASK_HINT` 是**两句话、两种情形**，不许合并：前者是「本 type 的密钥位上没有原值
 * 可还原」（新频道 / id 改名），后者是「这个键根本不属于本 type，它属于另一种频道」（换型残留）。
 * 合并成一句的后果是把「你该填一个凭据」说成「你贴了一个对不上任何已存值的占位符」——用户在
 * 新建频道时看到后一句会以为是自己复制错了。
 *
 * **写面与草稿测试（dry-run）共用这一句**，判据口径也共用：两侧都扫**全部已知类型**的密钥字段名
 * （`hasResidualMask` 的扫描面），只扫本 type 的话残留恰恰扫不到——残留的定义就是「字段不属于
 * 当前 type」。
 */
export const RESIDUAL_MASK_HINT =
  "草稿里有未还原的掩码占位（跨类型残留或改名残留），请重新填写真实凭据";

/** 合并结论。 */
export type ChannelMerge =
  | {
      readonly ok: true;
      /** 合并后的频道数组（落盘用；非数组输入原样穿过，形状判据归输入闸门）。 */
      readonly channels: RawSettingValue;
      /**
       * 与 `channels` **同下标**：该条目里哪些字段的值**原样来自存量**。
       *
       * 这份清单是「写面拒新增、不动存量」的执行依据：只有不在清单里的字段才重新接受合法性
       * 判据。少了它，磁盘上一份**越界**的旧值会让此后每一次无关保存都被拒（用户改个名字存不
       * 下），而那不是用户造成的。
       */
      readonly inherited: readonly ReadonlySet<string>[];
      /**
       * 与 `channels` **同下标**：该条目里哪些**必填键是存量本就残缺、这次既没补上也没删掉**的。
       *
       * 它是「半坏条目不许锁死设置页」这条的执行依据（#1016 S3 的一处真实回归）：读面自 S3 起不再丢弃
       * 半坏条目（视图逐字外发，用户看得见它、也改得动它），而「必填键在场」曾是**绝对**判据，于是
       * 用户在升级之后手改出一条半坏条目，此后再改**别的**频道的名字也存不下去（每一次保存都 400）。
       * 0.2.9 的形态清理只在刻度推进时跑一次，救不了「升级后手改」这条路。
       *
       * 与 `inherited` 分开记而不并成一条：那条记的是「**值**原样来自存量」，而一个从未存在过的键
       * 没有值可沿用。合并成一条，两族判据都说不清自己为什么跳过。
       *
       * 刻意**只记必填键**：其余形状判据（缺 id、type 非法、内置在场）不归它管，故也不受它的放行。
       */
      readonly preexisting: readonly ReadonlySet<string>[];
    }
  | { readonly ok: false; readonly error: SettingInvalid };

/**
 * 掩码类拒收的**情形序号**：数字小的先说。
 *
 * 只有掩码判据需要排序，其余拒收（必填键显式删除）一律当场返回、不参与——它与掩码是互斥的两种
 * 手势，同一个键上不可能同时成立，排序它没有意义。序号镜像 dry-run 的两段次序（见 mergeChannels）。
 */
type MaskRejectRank = 0 | 1;

/** 单条合并结论（内部形态，与对外的 `ChannelMerge` 同构）。 */
type EntryMerge =
  | {
      readonly ok: true;
      readonly channel: RawSettingValue;
      readonly inherited: ReadonlySet<string>;
      readonly preexisting: ReadonlySet<string>;
    }
  | {
      readonly ok: false;
      readonly error: SettingInvalid;
      /** 掩码类拒收的情形序号；非掩码拒收（当场返回的那种）没有这个字段。 */
      readonly rank?: MaskRejectRank;
    };

const EMPTY: ReadonlySet<string> = new Set<string>();

/** 本 type 的密钥字段名（掩码在该键上才有「未修改」的语义）；不认识的类型给空清单。 */
function secretFieldsOfType(type: RawSettingValue): readonly string[] {
  if (type === "bark" || type === "webhook") return CHANNEL_SECRET_FIELDS[type];
  return NO_SECRET_FIELDS;
}

const NO_SECRET_FIELDS: readonly string[] = [];

/**
 * **全部**已知类型的密钥字段名（并集）：判「这个键上的掩码是不是跨 type 残留」的扫描面。
 *
 * 扫并集而不是本 type，与 redact 域 `hasResidualMask` 同一口径：残留的定义就是「字段不属于当前
 * type」，只扫本 type 永远扫不到它（bark 的 deviceKey 挂到 webhook 条目上时，本 type 的清单是空的）。
 * 事实源仍是 `CHANNEL_SECRET_FIELDS`（两端共享面）——本域不另抄一份清单，两份清单迟早漂。
 */
const ALL_SECRET_FIELDS: ReadonlySet<string> = new Set(Object.values(CHANNEL_SECRET_FIELDS).flat());

/**
 * 合并一个频道数组。
 *
 * @param incoming 提交上来的频道数组（掩码还原**之前**——掩码是本模块的五态之一，不在别处解）。
 * @param stored 存量频道数组（磁盘原样）。提交里没提到的键从它取值。
 */
export function mergeChannels(incoming: RawSettingValue, stored: RawSettingValue): ChannelMerge {
  // 非数组输入原样穿过，形状判据归输入闸门（`channels` 需要数组）；没有条目可逐条记账，两笔账都空。
  if (!Array.isArray(incoming)) {
    return { ok: true, channels: incoming, inherited: [], preexisting: [] };
  }
  const storedById = indexById(stored);
  const channels: RawSettingValue[] = [];
  const inherited: ReadonlySet<string>[] = [];
  const preexisting: ReadonlySet<string>[] = [];
  // 两种掩码拒收**不按条目顺序先到先得**，而是取更靠前的那一种（`NO_SOURCE` 先于 `RESIDUAL`）。
  // 判据是 dry-run 的执行次序：它先整批跑 unmask（本 type 密钥位无原值即整体失败），整批过了才扫
  // 残留。一份「换型后既缺自己的凭据、又剩着旧 type 的掩码」的提交里两条都成立，写面若按键序先到
  // 先得，两条链路就会对**同一份草稿**给出两个答案——那正是 F1/F2 要消灭的那个分叉。
  let masked: { readonly rank: MaskRejectRank; readonly error: SettingInvalid } | undefined;
  for (const item of incoming) {
    const read = mergeEntry(item, storedById);
    if (!read.ok) {
      if (read.rank === undefined) return { ok: false, error: read.error };
      if (masked === undefined || read.rank < masked.rank)
        masked = { rank: read.rank, error: read.error };
      continue;
    }
    channels.push(read.channel);
    inherited.push(read.inherited);
    preexisting.push(read.preexisting);
  }
  if (masked !== undefined) return { ok: false, error: masked.error };
  return { ok: true, channels, inherited, preexisting };
}

/**
 * 单条合并：五态 + 两条硬规则。
 *
 * 按 **id** 对齐存量，不按下标——数组顺序一变，按下标就会把 A 实例的凭据回填进 B。id 重复时取
 * 首条（与掩码还原的 `findById` 同一口径，两处不各取一条）。
 */
function mergeEntry(
  item: RawSettingValue,
  storedById: ReadonlyMap<string, Record<string, RawSettingValue>>,
): EntryMerge {
  // 形状不对的条目原样穿过：形状的判据在输入闸门（`频道项需要对象`），不在合并里再抄一份。
  if (!isRecord(item)) return { ok: true, channel: item, inherited: EMPTY, preexisting: EMPTY };
  const id = typeof item.id === "string" ? item.id : "";
  const base = sameKindBase(item, id, storedById);
  const merged: Record<string, RawSettingValue> = base === undefined ? {} : { ...base };
  const inherited = inheritedKeys(base, item);
  const required = requiredKeysOf(item.type);
  // 掩码类拒收不在第一个命中处返回，而是**扫完本条全部键后取情形序号最小的那一个**
  // （理由见 mergeChannels 的注释）。非掩码类拒收（必填键显式删除）仍当场返回：它与掩码是互斥手势，
  // 且 dry-run 根本不产生那句话，两者的先后没有跨链路契约。
  const state: EntryState = { merged, inherited, masked: undefined, rejected: undefined };
  for (const [key, value] of Object.entries(item)) {
    // 只有非掩码拒收会走到 false（掩码拒收记进 state.masked，扫完本条再一起返回）。
    if (!applyField(key, value, base, required, item.type, id, state)) {
      if (state.rejected === undefined) throw new Error("applyField 返回 false 却没记下拒收话术");
      return { ok: false, error: state.rejected };
    }
  }
  if (state.masked !== undefined) {
    return { ok: false, error: state.masked.error, rank: state.masked.rank };
  }
  return {
    ok: true,
    channel: merged,
    inherited,
    preexisting: preexistingGaps(base, merged, item.type),
  };
}

/** 一条正在合并的频道条目：合并结果本体 + 逐字段记账 + 待决的拒收。 */
type EntryState = {
  readonly merged: Record<string, RawSettingValue>;
  readonly inherited: Set<string>;
  /** 本条扫到目前为止**情形序号最小**的掩码拒收（undefined = 还没有）。 */
  masked: { readonly rank: MaskRejectRank; readonly error: SettingInvalid } | undefined;
  /** 非掩码拒收的话术（必填键显式删除）；只在 applyField 返回 false 的那一轮被写进，随即被读走。 */
  rejected: SettingInvalid | undefined;
};

/**
 * 逐字段把一个 verdict 落到 state 上。
 *
 * @returns `false` = 这一条**当场拒收**（仅非掩码拒收：必填键显式删除），调用方立刻返回；掩码拒收
 *   记进 `state.masked` 并返回 `true`，让本条其余键继续扫完——理由见 mergeEntry 的注释。
 */
function applyField(
  key: string,
  value: RawSettingValue,
  base: Record<string, RawSettingValue> | undefined,
  required: readonly string[],
  type: RawSettingValue,
  id: string,
  state: EntryState,
): boolean {
  const verdict = fieldVerdict(key, value, base, required, type, id);
  if (verdict.kind === "reject") {
    if (verdict.rank === undefined) {
      state.rejected = verdict.error;
      return false;
    }
    if (state.masked === undefined || verdict.rank < state.masked.rank) {
      state.masked = { rank: verdict.rank, error: verdict.error };
    }
    return true;
  }
  if (verdict.kind === "drop") {
    delete state.merged[key];
    return true;
  }
  if (verdict.kind === "keep") {
    state.inherited.add(key);
    return true;
  }
  state.merged[key] = value;
  // 原样带回（客户端把磁盘上的值原封不动交回来）不算本次改动，故不重新判它的合法性。
  if (base !== undefined && sameValue(value, base[key])) state.inherited.add(key);
  return true;
}

/**
 * 存量基底：按 id 对齐，且**只认同一种 type**。
 *
 * 按 id 不按下标——数组顺序一变，按下标就会把 A 实例的凭据回填进 B；id 重复时取首条（与掩码
 * 还原的 `findById` 同一口径，两处不各取一条）。
 *
 * **换型 = 换了一条**：字段集随 type 变，存量那批键对新类型是陌生键，按字段继承会把 bark 的
 * baseUrl 带进 webhook。与「整组替换」的旧行为同向——换型之后提交面就是全部。
 */
function sameKindBase(
  item: Record<string, RawSettingValue>,
  id: string,
  storedById: ReadonlyMap<string, Record<string, RawSettingValue>>,
): Record<string, RawSettingValue> | undefined {
  if (id === "") return undefined;
  const previous = storedById.get(id);
  if (previous === undefined || previous.type !== item.type) return undefined;
  return previous;
}

/** 提交里没提到的键：整条沿用存量，它们既不是本次改动，也不该被重新判一遍合法性。 */
function inheritedKeys(
  base: Record<string, RawSettingValue> | undefined,
  item: Record<string, RawSettingValue>,
): Set<string> {
  const inherited = new Set<string>();
  if (base === undefined) return inherited;
  for (const key of Object.keys(base)) {
    if (!Object.hasOwn(item, key)) inherited.add(key);
  }
  return inherited;
}

/** 单键的合并动作（`merged[key]` 之后该怎么变）。 */
type FieldVerdict =
  | { readonly kind: "keep" }
  | { readonly kind: "drop" }
  | { readonly kind: "write" }
  | {
      readonly kind: "reject";
      readonly error: SettingInvalid;
      /** 掩码类拒收的情形序号（见 `MaskRejectRank`）；非掩码拒收不带这个字段。 */
      readonly rank?: MaskRejectRank;
    };

const KEEP: FieldVerdict = { kind: "keep" };
const DROP: FieldVerdict = { kind: "drop" };
const WRITE: FieldVerdict = { kind: "write" };

/**
 * 五态里的前四态落到一个键上。**第五态（其它值 → 写入）是剩下的唯一出口**，故这里只返回「不写」。
 *
 * @param base 同 id 同 type 的存量条目（换型或新频道时为 undefined = 没有可沿用的原值）。
 */
function fieldVerdict(
  key: string,
  value: RawSettingValue,
  base: Record<string, RawSettingValue> | undefined,
  required: readonly string[],
  type: RawSettingValue,
  id: string,
): FieldVerdict {
  if (value === undefined) return KEEP;
  // 状态 2：掩码 = 用户没改它。**这一态只对密钥字段成立**——判据是「这个键上，掩码有没有
  // 『未修改』的语义」，而语义来自 `CHANNEL_SECRET_FIELDS`（掩码往返的唯一扩展点）：
  //   (a) 本 type 的密钥字段：必须有原值可沿用。存量同 id 同 type 的条目里没有这个键
  //       （新频道、id 改名）时 400 `NEW_CHANNEL_MASK_HINT`——放行就等于把 `********`
  //       当凭据写进磁盘，那条凭据从此报废，而用户以为自己填过；
  //   (b) **别的** type 的密钥字段名（跨 type 残留，如 bark→webhook 后剩的 deviceKey）：
  //       400 `RESIDUAL_MASK_HINT`。这一格绝不能放行成普通值——那正是掩码工作要消灭的
  //       「占位符落进磁盘」；也绝不能并进 (a) 的话术：那是另一种情形、另一种排查方向；
  //   (c) 非密钥键：`********` 只是一个**普通字符串**（用户把频道名写成八个星号是他的自由），
  //       走第五态正常写入。把它当哨兵的症状是「一条关于凭据的话出现在频道名字上」，或者
  //       更隐蔽的「界面显示新值、磁盘是旧值」——那次改名被静默吞掉。
  // 为什么不干脆只留 (a)+(b)：那正是把跨 type 残留当成普通值写进磁盘的写法，两条都不对。
  if (value === SECRET_MASK) {
    if (secretFieldsOfType(type).includes(key)) {
      if (base !== undefined && Object.hasOwn(base, key)) return KEEP;
      return { kind: "reject", rank: 0, error: { key: "channels", hint: NEW_CHANNEL_MASK_HINT } };
    }
    if (ALL_SECRET_FIELDS.has(key)) {
      return { kind: "reject", rank: 1, error: { key: "channels", hint: RESIDUAL_MASK_HINT } };
    }
    return WRITE;
  }
  // 状态 3 / 4：显式删除。必填键不在这里被删——那要 400，不是静默降级成一个打不通的空壳。
  // `required` 是两张必填键表的并集（含取值域类的 `auth`，见 requiredKeysOf）：删它造出的残缺条目
  // 会在输入闸门被拒，而那里的理由是「值非法」——与 `url` 同一条手势、另一句话，用户无从分辨。
  if (value === null || value === "") {
    if (required.includes(key)) return { kind: "reject", error: rejectDeletable(type, id, key) };
    return DROP;
  }
  return WRITE;
}

/**
 * 不可删除的键：身份键（`id` / `type`）+ 该类型的**两张**必填键表。
 *
 * 事实源是 shared 的两张表（src/shared/config-schema.ts，两端共享面）：在场必填键 `REQUIRED_KEYS`
 * 与取值域类必填键 `VALUE_DOMAIN_REQUIRED_KEYS`（webhook 的 `auth`）。身份键不在任何一张表里，
 * 因为它们的判据不是「在场」而是「条目还是不是同一条」——但**删掉它们的动作是同一类**，故合到
 * 一起判。
 *
 * **取值域类的必填键为什么也在这张清单里（#1016）**：本模块只回答「这次写把这个键变成了什么」，
 * 不回答「这个值合不合法」——所以 `auth` 的**取值判据**（必须落在 WEBHOOK_AUTHS 里）仍然只在输入
 * 闸门。但「能不能删」是另一个问题，而它的答案与 `url` 一样是「不能」：客户端把 `auth` 清空成
 * `null` / `""` 时，本模块过去按「非必填键显式删除」把键 DROP 掉，删键造出的那条频道随即被输入闸门以
 * 「auth 非法」400 拒收——写面对 `auth` 的缺席与非法共用一句话，于是**同一个手势的两种落点给出两
 * 句话，而用户看到的现象是「保存不进去」**：他清空一个必填键，得到的回执却在说值非法。与 `url` 被
 * 清空时撞「url 是必填键，不能删除」相比，`auth` 这一格是纯粹的话术错位（两条路都是 400，故不是
 * 放行了坏数据）。清空一个必填键之后仍然只有 400 一条路，故按必填键处理就是与 `url` 对称的那条路。
 *
 * **刻意不并进 `REQUIRED_KEYS`**：那张表的每个消费方（输入闸门的「缺 X」话术、`preexisting` 记账、
 * 清理步判据 #5）都是按「缺席即错」在用它，`auth` 混进去会让「它的判据是取值域」这条约定消失在一
 * 个布尔标记里。本模块要的只是「两张表的并集」，故读两张、不合并。
 *
 * **也不按 type 白名单硬编码**：按表查（无该项即空清单），新增一种频道类型时不必记得回来改这里——
 * 抄一份 type 清单的代价与抄一份必填键清单同一种，而这份清单的错处会当场造出「此后每次保存都 400」
 * 的频道。
 */
function requiredKeysOf(type: RawSettingValue): readonly string[] {
  if (typeof type !== "string") return IDENTITY_KEYS;
  return [
    ...IDENTITY_KEYS,
    ...(REQUIRED_KEYS[type] ?? NO_REQUIRED_KEYS),
    ...(VALUE_DOMAIN_REQUIRED_KEYS[type] ?? NO_REQUIRED_KEYS),
  ];
}

/** 表里没有该 type 时的空清单（与 `deliveredRequiredKeys` 的同名常量同一个意思，故同名）。 */
const NO_REQUIRED_KEYS: readonly string[] = [];

/** 删必填键的拒收话术：与输入闸门「缺少 X」分开——一个说的是「没交」，一个说的是「要删」。 */
function rejectDeletable(type: RawSettingValue, id: string, key: string): SettingInvalid {
  const label = typeof type === "string" && type !== "" ? type : "实例";
  const subject = id === "" ? "" : ` ${id}`;
  return { key: "channels", hint: `${label} 频道${subject} 的 ${key} 是必填键，不能删除` };
}

/**
 * 「存量本就残缺、这次既没补上也没删掉」的必填键（`ChannelMerge.preexisting` 的算法）。
 *
 * 判据是**两边都坏**：合并结果里这个键没交上来（空串 / 数字 / 缺席），且存量那一份**同样**没交上来。
 * 少任何一边都不记账——
 *   - 存量里是好的、这次坏了 → 是这次写做坏的，判据必须拒（否则「把合法配置写坏」会一路通行）；
 *   - 存量里没有这条（新建频道、换型、id 改名）→ 没有「本就残缺」可言，新建的缺键照常 400。
 *
 * 按键逐个判而不是按整条判：客户端在提交前会合法地扰动条目（剥空串的可选字段、按类型补比较默认值），
 * 于是「这条提交里的内容与磁盘逐字相同」是个**假**前提——拿它当放行条件，一批真实形态照样被锁死。
 * 键粒度的增量才与「用户到底动了什么」对齐。
 *
 * 显式的删除手势（`null`）不会走到这里：它在上面的 `fieldVerdict` 里就 400 拒掉了。「删掉一个必填
 * 键」的后果因此仍是一律被拒，只是拒在更早、更准的那一步，而不是混进这条放行里。
 */
function preexistingGaps(
  base: Record<string, RawSettingValue> | undefined,
  merged: Record<string, RawSettingValue>,
  type: RawSettingValue,
): ReadonlySet<string> {
  // 换型（base 为 undefined）= 换了一条，新类型的必填键在存量里没有对应物，不记账。
  if (base === undefined) return EMPTY;
  const gaps = new Set<string>();
  for (const key of deliveredRequiredKeys(type)) {
    if (isDeliveredRequired(merged[key])) continue;
    if (isDeliveredRequired(base[key])) continue;
    gaps.add(key);
  }
  return gaps;
}

/** 判「必填键在场」的那份清单（判据 firstMissing 用的同一份）。
 *
 *  与 `requiredKeysOf` 的**可删除**清单不是同一张，有两处不同，缺一不可：
 *   - 那张还含身份键（删 id / type 同样是 400）与取值域类必填键（删 `auth` 同样是 400）；
 *   - 这里只问「这个键在不在」——身份键在场与否由 `validateChannel` 判，与本账无关。
 *
 *  **取值域类必填键（`auth`）刻意不在这张账上**：`preexisting` 放行的前提是输入闸门**认这份清单**，
 *  而 `validateWebhookChannel` 对 `auth` 走的是取值域判据且**不查 preexisting**——把 `auth` 加进
 *  这张表只会让合并结论报出一个没有消费方的字段名，看起来放行了、实际上照样 400。加它要连判据层
 *  一起改（那是「存量本就残缺」的另一件事，不在本模块的处置范围内）。 */
function deliveredRequiredKeys(type: RawSettingValue): readonly string[] {
  if (type !== "bark" && type !== "webhook") return NO_REQUIRED;
  return REQUIRED_KEYS[type];
}

const NO_REQUIRED: readonly string[] = [];

/** 频道数组 → id → 首条该 id 的条目；不是对象或没有非空 id 字符串的项不进索引。 */
function indexById(list: RawSettingValue): Map<string, Record<string, RawSettingValue>> {
  const index = new Map<string, Record<string, RawSettingValue>>();
  if (!Array.isArray(list)) return index;
  for (const item of list) {
    if (!isRecord(item)) continue;
    const id = item.id;
    if (typeof id !== "string" || id === "") continue;
    if (!index.has(id)) index.set(id, item);
  }
  return index;
}

function isRecord(raw: RawSettingValue): raw is Record<string, RawSettingValue> {
  return typeof raw === "object" && raw !== null && !Array.isArray(raw);
}

/**
 * dsh-notifier config 域 —— 草稿测试（dry-run）的输入闸门：只认 draft.channels。
 *
 * 与写面（write）的三处不同，每一处都是提案 B1/B2 的逐条落实：
 * - 只审 channels：draft 顶层的其它键一律忽略（不 400），revision 直接忽略——
 *   dry-run 不做乐观并发，测的是眼前条目，不是版本链；
 * - 逐项只调 validateChannel（单条），跳过 requireBuiltinsPresent——草稿里可以只有
 *   目标频道一条，要求内置在场会把「单测一个新建 bark 频道」这个主场景直接拒掉；
 * - 掩码按 id 还原（复用 unmaskChannels）：新频道无源、id 改名带掩码都落到
 *   NEW_CHANNEL_MASK_HINT 的 400；还原后仍残留掩码字面量（跨 type 残留）整体拒绝，话术是
 *   RESIDUAL_MASK_HINT——**与写面对同一情形逐字同句**（两句都从 service/merge.ts import）。
 *   占位符不是凭据，发出去会进对端日志，剥离会替用户改配置（B2 选 400 那一支，并由判据钉住）。
 *
 * 本模块只做「输入 → 可投递的频道数组」，不读文件、不写盘、不记日志：调用方（api 域）
 * 拿到的已是还原后的原始条目，再经 normalizeConfig 在内存里归一化，全程零落盘。
 */
import { validateChannel } from "../input/index.ts";
import type { RawSettingValue } from "../model/type.ts";
import { hasResidualMask, unmaskChannels } from "../redact/index.ts";
import { NEW_CHANNEL_MASK_HINT, RESIDUAL_MASK_HINT } from "../service/merge.ts";

/** 草稿解析结论：成功带回还原后的频道数组（原始形态，调用方再归一化）；失败只带一句话。 */
export type ResolvedDraft =
  | { readonly ok: true; readonly channels: readonly RawSettingValue[] }
  | { readonly ok: false; readonly hint: string };

// 跨 type 残留掩码的拒绝理由**不在本模块另写一份**：占位符出现在密钥位上，说明草稿里的凭据
// 已经对不上任何已存值，而这句话写面也要一字不差地说。两句拒绝话术（NEW_CHANNEL_MASK_HINT /
// RESIDUAL_MASK_HINT）都从写面那一侧 import——它们是「写面与 dry-run 对同一情形必须逐字同句」这条
// 跨链路契约的字面量，两处各写一份时漂移是时间问题而不是会不会的问题，而漂了的后果正是本模块
// 存在的理由被推翻（同一份草稿在保存与试发两条路上得到两个答案）。
//
// 情形本身仍在本模块判：unmaskChannels 失败 = 本 type 密钥位无原值（第一句）；还原后
// hasResidualMask 命中 = 掩码落在别的 type 的密钥位上（第二句）。写面按同一情形分三段，
// 见 service/merge.ts 的 fieldVerdict。判据见 config-merge-roundtrip.test.ts 的「两条链路同句」一组。

/**
 * 解析 dry-run 草稿：draft 必须是对象，其 channels 必须是数组；按 id 还原掩码、扫残留、
 * 再逐项校验。三步任一失败即整体拒绝——半条还原的草稿没有「测一半」的语义。
 *
 * **掩码两步排在逐项校验之前**（#1016 S2）：写面不再透传陌生键，于是「webhook 条目上带一个
 * bark 的 deviceKey 占位」会先被陌生键判据接住，而那句话（`deviceKey 不是已知键`）对用户是
 * 误导——他真正要知道的是「你贴进来的凭据对不上任何已存值」。安全信号优先于形状信号。
 *
 * @param draft 请求体里的 draft（顶层其它键与 revision 由调用方忽略，不进这里）。
 * @param secrets 掩码还原的原值来源（调用方传已生效设置的 channels，含明文凭据、不外发）。
 */
export function resolveDraftChannels(
  draft: unknown,
  secrets: readonly RawSettingValue[] | undefined,
): ResolvedDraft {
  if (!isRecord(draft)) return fail("draft 需要对象");
  const raw = draft.channels;
  if (!Array.isArray(raw)) return fail("draft.channels 需要数组");
  const restored = unmaskChannels(raw, secrets);
  if (!restored.ok) return fail(NEW_CHANNEL_MASK_HINT);
  const channels = restored.channels;
  if (!Array.isArray(channels)) return fail("draft.channels 需要数组");
  for (const channel of channels) {
    if (hasResidualMask(channel)) return fail(RESIDUAL_MASK_HINT);
  }
  for (const item of channels) {
    const verdict = validateChannel(item);
    if (!verdict.ok) return fail(verdict.error.hint);
  }
  return { ok: true, channels };
}

function fail(hint: string): ResolvedDraft {
  return { ok: false, hint };
}

function isRecord(raw: unknown): raw is Record<string, RawSettingValue> {
  return typeof raw === "object" && raw !== null && !Array.isArray(raw);
}

/**
 * 设置默认形态。与 `type.ts` 分开：形状与默认值是两套导出面，混在一起会让只想引一个类型
 * 的调用方连同一份值表一起拖进来。
 */
import { DEFAULTS } from "../../../../shared/interface.ts";
import type { NotifyConfig } from "./type.ts";

/** 默认设置：缺键的兜底值，也是设置页展示的初始形态。
 *
 * 顶层默认值来自 src/shared/config-schema.ts 的 `DEFAULTS`（两端共享面的事实源），本域只补
 * `channels` 的两条内置条目——它们只在服务端物化，不进共享表。
 *
 * 逐键铺开而不是 `...DEFAULTS`：铺开会让 `quietHours` / `kindRoutes` / `allowKinds` 与共享表
 * **同引用**，而共享表还随客户端内联——谁就地改写谁就污染了另一个。逐键写死同时把键序也
 * 钉住：`Object.keys(DEFAULT_CONFIG)` 是净化闸的键序来源，顺序变了用户层净化结果的键序就跟着变。 */
export const DEFAULT_CONFIG: NotifyConfig = {
  notifyAsk: DEFAULTS.notifyAsk,
  notifyQuestion: DEFAULTS.notifyQuestion,
  notifyTaskDone: DEFAULTS.notifyTaskDone,
  notifySubagentDone: DEFAULTS.notifySubagentDone,
  notifyTaskError: DEFAULTS.notifyTaskError,
  notifyTurnEnd: DEFAULTS.notifyTurnEnd,

  // 渠道形态只有一处表达：下面两条内置条目。0.2.3 的顶层渠道键在升级时被搬进条目并删除。
  quietHours: {
    enabled: DEFAULTS.quietHours.enabled,
    windows: DEFAULTS.quietHours.windows.map((w) => ({ ...w })),
  },
  // 内置频道恒在场且恒在最前：默认表就带它们，投递投影据此物化；0.2.9 形态清理负责把磁盘上
  // 残缺的内置条目补成同一份形态（判据在 upgrade/steps.test.ts 的「与默认表逐字一致」）。
  channels: [
    { type: "browser", id: "browser", enabled: true, popup: true, sound: true, whenVisible: false },
    { type: "system", id: "system", enabled: true, popup: true, sound: true },
  ],
  kindRoutes: { ...DEFAULTS.kindRoutes },
  allowKinds: [...DEFAULTS.allowKinds],

  historyMaxAgeDays: DEFAULTS.historyMaxAgeDays,
};

/**
 * dsh-notifier config 域 —— 设置存取的实现：读 = 文件 → 净化 → 归一化 → 快照，写 = 掩码还原 → 校验 → 合并 → 落盘。
 *
 * 装配期同步读完文件：读面是同步的，留一个窗口就会有读者拿到尚未生效的默认值。
 */
import { createHash } from "node:crypto";
import type { ConfigDeps } from "../../deps.ts";
import {
  readTextFileSync,
  writeTextAtomic,
  CONFIG_FILE_NAME,
  notifierFile,
} from "../../../shared/interface.ts";
import {
  UNSAFE_KEYS,
  normalizeConfig,
  parseJsonObject,
  sanitizeSettings,
  validateSettingsWithMerge,
} from "../input/index.ts";
import { mergeChannels } from "./merge.ts";
import { projectForView } from "./view.ts";
import { DEFAULT_CONFIG } from "../model/index.ts";
import type {
  NotifyConfig,
  RawSettingValue,
  SettingInvalid,
  SettingsPatch,
  StoredSettings,
} from "../model/type.ts";
import { redactStored } from "../redact/index.ts";
import type { SettingsView, WriteResult } from "./type.ts";

/** 合并结论的包装：`merged` 为 undefined = 本次提交没有 `channels` 这个键（「没动它」）。 */
type MergeOutcome =
  | {
      readonly ok: true;
      readonly merged:
        | {
            readonly channels: RawSettingValue;
            readonly inherited: readonly ReadonlySet<string>[];
            readonly preexisting: readonly ReadonlySet<string>[];
          }
        | undefined;
    }
  | { readonly ok: false; readonly error: SettingInvalid };

/** 未装配时的占位：装配是必经路径，占位只是让字段不必每个使用点判空。 */
const UNINSTALLED: ConfigDeps = { logger: { warn: () => {} } };

const NOOP = (): void => {};

/** 通知设置：本插件配置文件的唯一存取点。 */
class ConfigStore {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;
  /** 落盘路径：DSH home 由环境决定、进程内不变，故随实例一次性定下。 */
  private readonly file = notifierFile(CONFIG_FILE_NAME);
  /** 装配入参（失败出口）。 */
  private deps: ConfigDeps = UNINSTALLED;
  /** 文件内容原样镜像：写回时以它为基底，才不会被一次保存抹掉不认识的键。 */
  private stored: StoredSettings = {};
  /** 用户层（净化后）：写面做掩码还原、视图做回显都要它。 */
  private user: Partial<NotifyConfig> = {};
  /** 生效设置（**投递投影**）：归一化补过默认值、收敛过越界，**不外发**——`current()` 拿它。 */
  private effective: NotifyConfig = DEFAULT_CONFIG;
  /** 视图投影（**外发**）：键子集 + 原样 + 掩码，**不补默认值**。与投递投影是两份数据，见 view 模块的文件头。 */
  private viewConfig: Partial<NotifyConfig> = {};
  /** 用户层修订号（内容摘要）：乐观并发的比较依据。 */
  private revision = 0;
  /** 写队列尾：新写挂在它后面，「读-改-写」不会交错。 */
  private tail: Promise<void> = Promise.resolve();

  /** 装配：读一次文件定下初值；此后只经 `write` 变更。 */
  install(deps: ConfigDeps): void {
    if (this.installed) throw new Error("dsh-notifier: config 域只能装配一次");
    this.installed = true;
    this.deps = deps;
    const read = readTextFileSync(this.file);
    // 没有文件与文件是空的，对读面是同一件事：都没有用户层。
    this.adopt(read.ok ? parseJsonObject(read.text) : {});
  }

  /** 卸载：放开装配入参并丢掉用户层快照——它同时是「用户层」与「磁盘状态」的记忆。 */
  release(): void {
    this.installed = false;
    this.deps = UNINSTALLED;
    this.adopt({});
  }

  /** 当前生效设置（**投递投影**：补过默认值、收敛过越界；含明文凭据，**不外发**）。
   *
   *  pipeline / sdk / stores / dry-run 全靠它，故它一行不改地继续喂 `normalizeConfig` 的结果。 */
  current(): NotifyConfig {
    return this.effective;
  }

  /** 设置页视图：脱敏后的用户层与生效值 + 修订号 + 可写性，同一刻取齐。 */
  view(): SettingsView {
    return {
      // `user` 是**存储原样**（只掩码）：陌生键也要看得见——净化后的 this.user 里没有它们，
      // 而它们确实还在文件里，视图不显示就等于「文件里有、界面里没有」两套事实。
      user: redactStored(this.stored),
      revision: this.revision,
      writable: true,
      // 视图投影**不是**投递投影（#1016 S3）：外发的是「磁盘原样 + 掩码」，补出来的默认值与被钳过的
      // 越界值留在域内。两者混用会让一次无关保存把磁盘形态改写成读面的实现——见 view 模块的文件头。
      effective: this.viewConfig,
    };
  }

  /**
   * 写：整段挂进写队列，队列内完成按字段合并（含掩码还原）→ 校验 → 落盘 → 刷新快照。
   *
   * 为什么不把合并与校验留在队列外：两者都要读存量（合并沿用哪些键、判据据此决定重判哪些），
   * 队列外读到的存量会被并发的另一次写抽走。详见 `apply` 的注释。
   *
   * `apply` 必须**直调 commit，不得再 enqueue**：enqueue 同步把 tail 设成 result.then(...)，
   * task 内再 enqueue 就是等自己刚挂上去的 tail——那个 tail 排在自己后面，自己不返回它就不 resolve。
   * 故 apply 与 commit 之间不经队列，是**结构上**写死的，不靠调用方记得。
   */
  async write(patch: SettingsPatch, expectedRevision?: number): Promise<WriteResult> {
    return this.enqueue(() => this.apply(patch, expectedRevision));
  }

  /**
   * 一次写的全过程：按字段合并（含掩码还原）→ 校验合并结果 → 落盘 → 刷新快照。
   *
   * **整段在写队列内**，合并与校验都算在内（issue #1016 批次 B）。原来还原与校验在队列外，
   * 于是它们读到的存量是「入队那一刻」的：并发的两次写里，后一次会用前一次落盘**之前**的
   * 用户层去还原掩码、判定「原样带回」，基线跟着另一次写漂走。把它们移进队列后，合并、判据
   * 三者看到的是同一份存量快照。
   *
   * 顺序不可换（#1016 S2）：合并必须**先于**校验——判据审的是合并后的条目，而「删键之后必填键
   * 此刻为空」这条判据只有合并之后才问得出；校验必须早于落盘，否则非法值会先写进文件。掩码在
   * 合并里解（五态之一，见 merge 模块），不再有独立的还原步骤：两条路径各解一次会让「掩码在
   * 哪一步变成原值」有两个答案，而判据看到的形态与落盘的形态就必须逐字一致。
   *
   * 校验与合并之间不净化：磁盘上**存量**的陌生键不在提交里，合并原样沿用，一次保存抹不掉它们；
   * 而**本次提交**的陌生键由判据 400（#1016 S2 删掉了 extras 透传面）。0.2.3 的顶层渠道键已由
   * upgrade 域在装配期搬走，写面收到它们会被校验直接拒（退役键清单），不在这里做二次翻译。
   * 合并那一侧读哪份存量（磁盘原样，不是 effective）由 `mergePatchChannels` 的注释交代。
   */
  private async apply(patch: SettingsPatch, expectedRevision?: number): Promise<WriteResult> {
    const outcome = mergePatchChannels(patch.channels, this.stored);
    if (!outcome.ok) return { ok: false, reason: "invalid", error: outcome.error };
    // 判据看**合并后**的频道条目（形状与必填键）；顶层键仍按提交面逐值判——顶层没有按键合并这回事。
    const verdict = validateSettingsWithMerge(patch, outcome.merged);
    if (!verdict.ok) return { ok: false, reason: "invalid", error: verdict.error };

    const subject: SettingsPatch =
      outcome.merged === undefined ? patch : { ...patch, channels: outcome.merged.channels };
    const incoming = writableEntries(subject);
    return this.commit(incoming, expectedRevision);
  }

  /**
   * 提交：版本比对 → 合并 → 原子落盘 → 采纳。
   *
   * 整段在写队列内执行：比对与写入之间若能被另一次写插入，乐观并发就形同虚设
   * ——两次写都读到同一旧版本、都判定通过，后写的把先写的悄悄覆盖。
   *
   * `expectedRevision` 与合并结果的 `inherited` **语义不同，不许合并成一个参数**：
   * 前者是**内容摘要**比对，防的是「两个客户端同时改」的丢失更新（防的是覆盖）；
   * 后者是**同 id 同 type 同名字段**的沿用清单，解的是「存量非法值不该因一次无关保存被拒」的
   * 过度拒绝（防的是错杀）。两者一个按内容断版本、一个按字段认改动，混在一起会让任一条判据
   * 悄悄变成另一条：把字段比对当版本号，用户改一个字段就凭空冲突；把版本号当字段比对，
   * 别的键变过就会让这次保存看起来「没改过」。
   */
  private async commit(incoming: StoredSettings, expectedRevision?: number): Promise<WriteResult> {
    if (expectedRevision !== undefined && expectedRevision !== this.revision) {
      return { ok: false, reason: "conflict" };
    }
    const merged: StoredSettings = { ...this.stored, ...incoming };
    const written = await writeTextAtomic(this.file, `${JSON.stringify(merged, null, 2)}\n`);
    if (!written.ok) {
      this.deps.logger.warn(`dsh-notifier: 配置写入失败 — ${written.reason}`);
      return { ok: false, reason: "unavailable" };
    }
    this.adopt(merged);
    return { ok: true, view: this.view() };
  }

  /**
   * 文件内容到达：镜像原样留下，**两份投影**由它各自派生（#1016 S3）。
   *
   * 这一行是「读面拆两条通道」的落点：`effective` 走归一化（投递侧要完整形态），`viewConfig` 走
   * 键子集投影（外发侧要磁盘原样）。两者曾共用一份数据，于是「补出来的默认值」被当成用户存过的值
   * 交回磁盘——见 view 模块的文件头与 `view()` 的注释。
   */
  private adopt(stored: StoredSettings): void {
    this.stored = stored;
    this.user = sanitizeSettings(stored);
    this.effective = normalizeConfig(stored);
    this.viewConfig = projectForView(stored);
    this.revision = revisionOf(stored);
  }

  /** 把一次写挂到队列尾；前一次无论成败，后一次都照常执行。 */
  private enqueue(task: () => Promise<WriteResult>): Promise<WriteResult> {
    const result = this.tail.then(task, task);
    this.tail = result.then(NOOP, NOOP);
    return result;
  }
}

/** 本域唯一的存取点实例：类不外放，外面 `new` 不出第二份设置状态。 */
export const configStore = new ConfigStore();

/**
 * 提交里的 `channels` → 合并结果（掩码也在这一步解，见 merge 模块的五态）。
 *
 * 基线取 `stored`（**磁盘原样**）而不是 `effective`：合并的目的是「客户端没带的字段落盘后还在」，
 * 而 effective 是归一化补过默认值、剥过空串、钳过越界的形态——拿它当基底等于把一份补值写回文件，
 * 让磁盘上的形态随读面实现漂移。
 *
 * 提交里没有 `channels` 这个键时给 `undefined`（「这次没动它」）：顶层仍是整值替换，提交里没有
 * 的键不进 `merged`，由 `commit` 的基底原样带过去。
 */
function mergePatchChannels(
  channels: RawSettingValue | undefined,
  stored: StoredSettings,
): MergeOutcome {
  if (channels === undefined) return { ok: true, merged: undefined };
  const merged = mergeChannels(channels, stored.channels ?? []);
  if (!merged.ok) return { ok: false, error: merged.error };
  return {
    ok: true,
    // 两笔账整份带过去：值域判据看 inherited（「值原样来自存量」），「必填键在场」看 preexisting
    // （「键的缺席本来就来自存量」）。判据侧按同下标取用，见 MergedChannelScope。
    merged: {
      channels: merged.channels,
      inherited: merged.inherited,
      preexisting: merged.preexisting,
    },
  };
}

/** 提交体 → 可写入的原始设置：只剔除原型链危险键，契约不认识的键原样放行（抹掉属于静默破坏）。 */
function writableEntries(patch: SettingsPatch): StoredSettings {
  const entries: Record<string, RawSettingValue> = {};
  for (const [key, value] of Object.entries(patch)) {
    if (value === undefined || UNSAFE_KEYS.includes(key)) continue;
    entries[key] = value;
  }
  return entries;
}

/**
 * 修订号：用户层内容的摘要。
 *
 * 键序不是内容，换键序不该算改动；但排序必须**递归**做——`JSON.stringify` 的 replacer
 * 数组会作用到每一层，用它排顶层键会把嵌套键（频道、免打扰、路由表）统统丢掉，两份内容
 * 不同的设置于是算出同一个修订号，乐观并发的版本冲突漏判。
 */
function revisionOf(stored: StoredSettings): number {
  return createHash("sha256").update(stableJson(stored), "utf8").digest().readUInt32BE(0);
}

/** 稳定序列化：对象递归按键排序，数组保持原序（数组顺序是内容的一部分）。 */
function stableJson(value: RawSettingValue): string {
  if (isJsonArray(value)) return `[${value.map(stableJson).join(",")}]`;
  if (isJsonObject(value)) {
    const fields = Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${stableJson(value[key])}`);
    return `{${fields.join(",")}}`;
  }
  return JSON.stringify(value);
}

/** JSON 数组：`readonly` 数组落在 `Array.isArray` 的收窄结果之外，用守卫补上。 */
function isJsonArray(value: RawSettingValue): value is readonly RawSettingValue[] {
  return Array.isArray(value);
}

/** JSON 对象：排除数组与 `null`（`typeof null` 也是 `"object"`）。 */
function isJsonObject(value: RawSettingValue): value is StoredSettings {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * dsh-notifier config 域 —— **视图投影**（#1016 重构第 4 步：读面拆「投递投影 / 外发视图」）。
 *
 * 读面有两条出口，它们要的东西**相反**，过去共用一份数据（`normalizeConfig` 的结果）才一直互相别扭：
 *   - **投递投影**（`normalizeConfig`，service 域内私有）：缺键补默认、越界钳回合法域、认不出的条目丢弃。
 *     域内消费者（pipeline / sdk / stores / dry-run）要的是「一份一定可用的完整设置」，**宿主的解释在
 *     这一侧就该做完**，故它一行都不改地继续喂 `current()` / `readConfig()`。
 *   - **视图投影**（本模块，外发客户端）：**只做「键子集 + 原样 + 掩码」**。补出来的默认值是宿主侧的
 *     解释，外发出去等于让客户端把它当成「用户存过的值」原样提交回磁盘——一次无关保存就把磁盘形态改写成
 *     读面的实现（越界值被钳成 0、非法枚举被换成 custom），而用户什么都没碰过。
 *
 * 因此本模块的纪律是「**除掩码外一个字都不改**」：不补默认值、不钳越界、不丢非法值、不补内置条目、
 * 不投影旧键。磁盘上是什么，客户端看见的就是什么。
 *
 * 两处与读面不同，且都是刻意的：
 *   1. **顶层只取 11 个已知键**（`DEFAULT_CONFIG` 的键集，`channels` 是其中之一），磁盘上的顶层陌生键
 *      不进视图。理由不是洁癖：写面对未知顶层键一律 400（`verdictOf` 的 CONFIG_KEYS 判据），把它交给
 *      客户端只会被原样带回并当场被拒——视图给出一份「提交必然 400」的数据，用户改个名字都存不下去。
 *   2. **顶层缺键取默认表的值**（键集恒为 11 个）。设置页要渲染全部 11 个控件，缺一个就是一处空白；而
 *      顶层不存在「用户写过什么被改写」——值一旦在磁盘上就原样穿过，缺的才给默认值。这与上面的「不补默认值」
 *      不冲突：那条纪律针对的是 `channels` **条目内部**的补值，而那正是会被交回磁盘的那部分。
 *
 * **本模块不做任何键名映射**——这是 S3 的一项承重依赖，理由见 `projectForView` 的注释。
 */
import { DEFAULT_CONFIG } from "../model/index.ts";
import type { NotifyConfig, RawSettingValue, StoredSettings } from "../model/type.ts";
import { redactStored } from "../redact/index.ts";

/**
 * 视图的顶层键集：默认表的 11 个键。派生而不是另抄一份清单——抄一份的症状是「模型加了键而视图里没有它」，
 * 设置页会少一个控件且无从察觉。
 */
const VIEW_KEYS: readonly (keyof NotifyConfig)[] = Object.keys(
  DEFAULT_CONFIG,
) as (keyof NotifyConfig)[];

/**
 * 视图投影：磁盘形态 → 外发给客户端的那一份（凭据已掩码）。
 *
 * **不做任何键名映射**：磁盘上频道条目里的陌生键原样进视图，客户端原样带回，写面 merge 判它「原样带回」
 * 进 `inherited` 因而不重判值域，于是它既不丢也不撞 400。这条链的前提是**客户端不对该键做任何投影**：
 * 将来客户端若把它映射成别的键名（或改名/丢弃），写面看到的就是一次「本次提交」而不是「原样带回」，随即
 * 400（`validateKnownKeys`）。改动客户端 `stripChannelEmpties` / `normalizeChannelForCompare` 的键清单时
 * 必须一并重看本段。
 */
export function projectForView(stored: StoredSettings): Partial<NotifyConfig> {
  // 累加器用可写索引签名（`StoredSettings` 是只读的存储镜像，构造中的对象不是存储）。
  const picked: Record<string, RawSettingValue> = {};
  for (const key of VIEW_KEYS) {
    const onDisk = stored[key];
    picked[key] = onDisk === undefined ? DEFAULT_CONFIG[key] : onDisk;
  }
  // 掩码是本模块唯一允许的加工，且实现在 redact 域（`redactStored` = 键子集原样 + 掩码）：凭据明文出到
  // 界面是安全问题，两个出口必须共用同一份掩码实现，抄一份就一定会漂。
  return redactStored(picked) as Partial<NotifyConfig>;
}

packages/dsh-notifier/test/integration/c.source:
/**
 * dsh-notifier —— 写面**按字段合并**在 10 种磁盘形态上的形态回归（#1016 S2）。
 *
 * **文件名在 S4 才改对（此前是历史名 `config-write-scope-roundtrip`）**：它诞生时断的是「写面范围
 * （scope）」，而那个面已在 #1016 S2 的收尾里删掉（零消费者，且与 inherited 对「提交没带某字段」
 * 给相反答案）。S3 收尾时按下改名，是因为它被三处登记引用——scripts/test/service-contract-wiring.test.ts
 * 的测试面清单、mutation-topology.json 的 config/channels 段 testFiles、以及从拓扑派生的
 * vitest.stryker.d/*.config.ts——改一个字要连带重冻结这三份，而那一步的净收益只是改一行文件名。
 * S4 本来就要重写本文件的判据，迁移成本降到最低，于是连同台账一并改对，改完跑
 * `pnpm stryker:gen` 重派生。**要保留下来的从来不是那个名字，是它枚举的 10 种磁盘形态**——
 * 每一种都是真实存量配置文件里真会出现的样子，而每一种都曾是「用户只改一个名字，却让整条频道的
 * 凭据/开关/超时一起被改写」的候选现场。
 *
 * 判据从「假阳性 = 0」升级成**落盘形态回归**：每种形态都断言「走完真实往返链、只改 name 之后，
 * 落盘的那条频道**逐字等于**预期形态」——预期形态是手写的字面量，不是「跑一遍看看输出什么」。
 * 合并的实现、读面的归一化、出口的掩码、客户端的剥空串，任一处漂了都会打红其中一条。
 *
 * 链路与真客户端逐段对应（行号对客户端 index.tsx / client/settings/diff.ts / server/config/impl/service）：
 *   磁盘 → projectForView（读面的**视图通道**：键子集 + 原样 + 掩码）→ GET /config 外发
 *        → snapshotBaseline（loadCard 建基线与草稿）→ 用户改一个字段（assignChannelFields）
 *        → diffSettingsPayload（保存时算增量）→ mergeChannels（写面按字段合并，掩码在这一步
 *        按 id 换回存量原值）→ validateSettingsWithMerge（判据审合并结果）
 *
 * **越界值原样保留是 S3 的既定语义（读面不再归一化），不是回归**：#1016 S3 把读面拆成
 * 「投递投影 / 外发视图」两条通道，投递侧一行未改（`current()` 仍是 normalizeConfig 的结果），而**外发
 * 的视图只做键子集 + 原样 + 掩码**。于是磁盘上越界的 `timeoutMs: 999999`、越界的 `timeoutSec: 99999`、
 * 不在白名单的 `preset: "nope"` 会原样交给客户端、原样交回写面，被合并判成「原样带回」进 inherited 而
 * 不重判值域，最终**落盘保持磁盘原值**。S2 之前它们会被读面钳成 0 / "custom" 再落盘——那是「宿主的解释
 * 被当成用户的值写回磁盘」，正是 S3 要消灭的那件事。形态四与形态十的字面量据此翻转。
 *
 * 顺带被 S3 翻转的还有**读面曾经补出来、而视图不再补的键**（各条 bark/webhook 的 `enabled: false`）：
 * 它们过去由 normalizeConfig 物化、经客户端原样带回而落盘，现在既没人补、客户端也不补，于是**落盘上
 * 就没有这个键**。而 `levels: {} / timeoutMs: 0 / headers: {} / timeoutSec: 0 / preset: "custom" /
 * auth: "none"` 仍在——它们由**客户端的比较规范形**（shared/channel-compare.ts）补，两端共用那一份，
 * 与 S3 无关。逐形态的字面量把这条界线钉死：哪几个键是宿主侧的解释、哪几个是客户端侧的补齐。
 *
 * 第三处与 S2 之前的版本不同，同样是为了「模拟链路不再与真实链路分叉」：
 *   - 除 `channels` 外的十条磁盘形态都**带上了两条内置条目**。0.2.4 的配置形态割接会把内置补进文件、
 *     写面又拒收缺内置的提交，所以「磁盘上没有内置」只可能是 0.2.3 及更早的文件；而读面自 S3 起不再物化
 *     它们，那样的文件在设置页上提交任何一次都会撞「内置渠道不能删除」的 400。形态七与形态八仍以「没有
 *     内置」为前提，各自记着它自己的那条理由。
 *   - 提交体**带着掩码**直接进 mergeChannels，不再由本文件调 unmaskChannels 预还原。生产写面
 *     早已不走那条还原路径（掩码是合并的五态之一），继续在测试里走它就是拿一条不存在的链路
 *     冒充真实链路。
 *   - 判据入口是 validateSettingsWithMerge（审合并结果 + inherited），不再有基线与 scope。
 *
 *
 * 文件末尾另有一组「半坏条目不许锁死设置页」的判据（#1016 S3 回归修复）：S3 让读面不再丢弃半坏
 * 条目，而写面的「必填键在场」是**形状**判据、不看增量，于是「升级后手改文件造出的半坏条目」会把
 * 此后每一次保存都变成 400——比 S3 之前更差。形态八断言的是**升级清理之后**的磁盘形态，那一步只在
 * 刻度推进时跑一次，救不了「升级后手改」这条路；末尾那组判据钉的是写面这一侧不许锁人。
 *
 * 再往后一组是**取值域类必填键**（webhook 的 `auth`）的删除手势：它在合并层过去按「非必填键显式删除」
 * 被删键，删键造出的残缺随即被输入闸门以「auth 非法」拒收，而 `url` 被清空时说的是「url 是必填键，
 * 不能删除」——同一条手势、两种话术，用户无从分辨是哪一处出错。这一组钉的是两边对齐后的样子，
 * 以及三条不许跟着变宽的边界（键缺席不动、值域判据仍归判据层、掩码通道不回归）。
 *
 * 无文件系统、无网络、不碰 DSH_HOME：本文件只跑纯函数，落盘纪律不适用。
 */
import { describe, expect, it } from "vitest";

import { validateSettingsWithMerge } from "../../src/server/config/impl/input/index.ts";
import { resolveDraftChannels } from "../../src/server/config/impl/draft/index.ts";
import type { ResolvedDraft } from "../../src/server/config/impl/draft/index.ts";
import type { RawSettingValue, StoredSettings } from "../../src/server/config/impl/model/type.ts";
import { mergeChannels } from "../../src/server/config/impl/service/merge.ts";
import type { ChannelMerge } from "../../src/server/config/impl/service/merge.ts";
import { projectForView } from "../../src/server/config/impl/service/view.ts";
import { REQUIRED_KEYS, VALUE_DOMAIN_REQUIRED_KEYS } from "../../src/shared/interface.ts";
import {
  assignChannelFields,
  diffSettingsPayload,
  snapshotBaseline,
} from "../../src/client/settings/diff.ts";

/** 掩码占位字面量：与设置页、redact 域、merge 域同一份跨端契约（独立写出，不从源码 import）。 */
const MASK = "********";

/** 合法 bark：写面要求 id / baseUrl / deviceKey 非空。 */
const BARK = { type: "bark", baseUrl: "https://api.day.app", deviceKey: "key-1" };

/**
 * 合法 webhook：凭据四个键**都**在磁盘上。
 *
 * 为什么不能只写 url：**掩码还原按 id 对齐取原值**，磁盘上没这个键就换不回真凭据；而外发视图
 * 只对**非空**的凭据掩码（空串不掩，见 redact 域的注释），所以四个键都得在磁盘上带着真值，
 * 「凭据在磁盘上是空串」那一支由形态九单独覆盖。
 */
const HOOK = {
  type: "webhook",
  url: "https://example.test/hook",
  token: "tok",
  username: "u",
  password: "p",
  headerName: "X-Key",
  headerValue: "hv",
};

/** 一条频道（存储层形状不受契约约束，按原始值看）。 */
type Channel = Record<string, RawSettingValue>;

/** 一次往返的结果。 */
type RoundTrip = {
  /** 落盘的频道数组（合并结果，即 commit 要写进文件的那份）。 */
  readonly persisted: readonly Channel[];
  /** 判据结论（机制不改变它：审的是合并结果，不带任何基线）。 */
  readonly verdictOk: boolean;
  /** 用户改的那条在提交里的形态（掩码还在——它要到合并那一步才换回原值）。 */
  readonly submitted: Channel;
  /** 提交面里的**全部**频道：判别「客户端有没有看见 / 有没有交回某一条」时用它，而不是只看被改那条。 */
  readonly payload: readonly Channel[];
};

/**
 * 走一遍真实往返链：磁盘 → … → 写面合并 → 判据。
 *
 * @param disk 磁盘上的配置文件内容（原样，未经净化/归一化）。
 * @param editId 用户改的是哪条频道。
 * @param part 用户在界面上改的字段（其余一律原样）。
 */
function roundTrip(disk: StoredSettings, editId: string, part: Record<string, unknown>): RoundTrip {
  const { payload, merged } = submitDraft(disk, editId, part);
  if (!merged.ok) throw new Error("合并被拒：" + JSON.stringify(merged.error));
  const verdict = validateSettingsWithMerge(
    { channels: merged.channels as RawSettingValue[] },
    merged,
  );

  const submitted = (payload as Channel[]).find((item) => item.id === editId);
  if (submitted === undefined) throw new Error("提交里没有 id=" + editId + " 的频道");
  return { persisted: merged.channels as Channel[], verdictOk: verdict.ok, submitted, payload };
}

/**
 * 同一条链，但**停在合并为止**、且不在合并被拒时抛错——「必填键删除手势被拒」正是末尾那组判据要断言的
 * 结论，抛错就断言不到话术。抛错版的 roundTrip 保留给那 13 条形态判据（合并被拒在那里就该炸）。
 */
function submitDraft(
  disk: StoredSettings,
  editId: string,
  part: Record<string, unknown>,
  removeId?: string,
): { readonly payload: Channel[]; readonly merged: ChannelMerge } {
  // 读面的**视图通道**（#1016 S3）：键子集 + 原样 + 掩码，**不补默认值**——这才是 GET /config 外发的那份。
  // （投递投影 normalizeConfig 是另一条通道，只服务域内消费者，不在这条链上。）
  const effective = projectForView(disk);
  // GET /config 外发的 effective（凭据掩码）→ 客户端建基线与草稿（loadCard）。
  const snapshot = snapshotBaseline(effective as unknown as Record<string, unknown>);
  const draft = Object.assign({}, snapshot) as Record<string, unknown>;
  // 用户改一个字段：逐段照搬 chPatch——先 slice 出新数组再改单项。这一步不能图省事就地改：
  // loadCard 的草稿是基线的**浅**拷贝，两边共用同一个 channels 数组，就地改会把基线一起改掉，
  // 于是 diff 恒等、永远提交不出 channels。
  const list = (draft.channels as Channel[]).slice();
  const index = list.findIndex((item) => item.id === editId);
  if (index < 0) throw new Error("磁盘形态里没有 id=" + editId + " 的频道");
  list[index] = assignChannelFields(list[index], part) as Channel;
  // 「把这条频道删掉」也是设置页上真实存在的手势，与编辑同一条链（草稿少一条 → 整组 channels 进提交面）。
  draft.channels = removeId === undefined ? list : list.filter((item) => item.id !== removeId);

  // 保存：整组提交（改任一字段都会把 channels 整组带上）。**掩码原样带走**，还原是合并的职责。
  const payload = diffSettingsPayload(draft, snapshot);
  if (!Array.isArray(payload.channels)) throw new Error("改了频道却没有产生 channels 提交");

  // 写面：按字段合并（基线 = 磁盘原样）。
  return {
    payload: payload.channels as Channel[],
    merged: mergeChannels(payload.channels as RawSettingValue, disk.channels ?? []),
  };
}

/** 按 id 取一条；取不到当场失败（形态回归里「取不到」本身就是回归）。 */
function byId(list: readonly Channel[], id: string): Channel {
  const found = list.find((item) => item.id === id);
  if (found === undefined) throw new Error("落盘结果里没有 id=" + id + " 的频道");
  return found;
}

/**
 * 磁盘形态里的频道数组（dry-run 的原值来源）。存储层的 `channels` 是宽联合而不是数组，
 * 这里按「是数组就用，不是就当没有」收一下——本文件的磁盘形态都由 `diskOf` 造出来，那边恒是数组。
 */
function channelsOf(stored: StoredSettings): readonly RawSettingValue[] {
  const list = stored.channels;
  return Array.isArray(list) ? list : [];
}

/** 落盘结果的频道 id 列表（顺序是内容的一部分，见 service 域 stableJson 的注释）。 */
function idsOf(list: readonly Channel[]): string[] {
  return list.map((item) => String(item.id));
}

/**
 * 两条内置条目的形态：0.2.4 的配置形态割接把它们补进文件，0.2.9 的形态清理保证它们恒在场
 * （#1016 S3 起读面不再物化它们），所以除形态七 / 形态八外的磁盘形态都带它们。
 */
const BROWSER: Channel = {
  type: "browser",
  id: "browser",
  enabled: true,
  popup: true,
  sound: true,
  whenVisible: false,
};

const SYSTEM: Channel = {
  type: "system",
  id: "system",
  enabled: true,
  popup: true,
  sound: true,
};

/** 磁盘形态：两条内置 + 用户自己配的条目（真实文件里就是这个样子）。 */
function diskOf(...entries: Channel[]): StoredSettings {
  return { channels: [BROWSER, SYSTEM, ...entries] };
}

/**
 * 十种磁盘形态 + 每种的**预期落盘**。
 *
 * kept 是被改的那条在落盘时的完整字面量：磁盘原样保住的键、客户端交上来的归一化补值、以及用户
 * 改的 name，三者叠加后的终态。手写字面量而不是「跑一遍取输出」——后者会把任何实现（包括写错的
 * 实现）都冻成「预期」。
 */
type Form = {
  readonly label: string;
  /** 磁盘上的配置文件内容（原样）。 */
  readonly disk: StoredSettings;
  /** 用户改哪条、改什么。 */
  readonly editId: string;
  readonly part: Record<string, unknown>;
  /** 落盘后全部频道的 id 顺序。 */
  readonly keptIds: readonly string[];
  /** 被改那条在落盘时的完整形态。 */
  readonly kept: Channel;
  /** 这一形态特有的事实（形态专属的陷阱），逐条断言。传入本形态，读它的 disk 不必靠下标。 */
  readonly also?: (form: Form, trip: RoundTrip) => void;
};

