/**
 * dsh-notifier config 域 redact 块 —— 凭据的掩码往返（安全模块）。
 *
 * 为什么单独成文件：这条对称（读出去掩码、写回来按 id 还原）是凭据不掉明文的**唯一**保证，
 * 而它泄漏或毁掉凭据的方式都是静默的——没有这条对称，凭据只有两种结局：明文出到界面与日志，
 * 或被掩码字面量覆盖成 `********` 从此再也发不出去。故两个方向各守一遍。
 *
 * 掩码字面量在测试里独立写出，不从源码导入：设置页把它渲染进 password 输入框并把用户没改动的
 * 值原样提交回来（`src/client/index.tsx` 的 `placeholder: "********"`），两侧一旦不一致，界面
 * 回填的那份就会被当成**新凭据**写进文件。故这里断言的是跨端契约，不是实现细节。
 *
 * 本块是 L1 纯函数块，直引 `impl/redact/index.ts`。
 */
import { describe, expect, it } from "vitest";

import { redactConfig, unmaskChannels } from "../../../src/server/config/impl/redact/index.ts";
import type { NotifyConfig, RawSettingValue } from "../../../src/server/config/impl/model/type.ts";

/** 掩码占位：与设置页共享的契约字面量。 */
const MASK = "********";

/** 两个实例的 bark 频道：id 对齐用例需要「有原值可还原」的第二个实例。`as const` 保住判别键的字面量类型。 */
const BARK_A = {
  type: "bark",
  id: "bark:a",
  baseUrl: "https://api.day.app",
  deviceKey: "key-a",
  name: "A",
  enabled: true,
} as const;
const BARK_B = {
  type: "bark",
  id: "bark:b",
  baseUrl: "https://api.day.app",
  deviceKey: "key-b",
  name: "B",
  enabled: true,
} as const;

/** 完整 webhook 频道：三类密钥字段齐全。 */
const WEBHOOK = {
  type: "webhook",
  id: "webhook:hook",
  url: "https://example.test/hook",
  enabled: true,
  auth: "bearer",
  token: "t-1",
  username: "u-1",
  password: "p-1",
  headerName: "X-Token",
  headerValue: "h-1",
} as const;

/** 裸值：构造存储层里真实可能存在、契约类型却排除掉的形态（如 channels 是字符串）。 */
function bare(value: unknown): RawSettingValue {
  return value as RawSettingValue;
}

/** 取还原后的频道数组；被拒即当场失败（否则断言会落在一个不存在的数组上）。 */
function restoredOf(
  patch: RawSettingValue,
  existing?: RawSettingValue,
): Array<Record<string, RawSettingValue>> {
  const result = unmaskChannels(patch, existing);
  if (!result.ok) throw new Error(`期望还原成功，实际被拒：${JSON.stringify(patch)}`);
  return result.channels as Array<Record<string, RawSettingValue>>;
}

describe("redactConfig：读出口只出掩码", () => {
  it("密钥字段换成掩码占位，非密钥字段保持明文（把用户名或头名一起掩掉，设置页就看不清自己填过什么）", () => {
    const masked = redactConfig({ channels: [BARK_A, WEBHOOK] });
    const [bark, webhook] = masked.channels ?? [];
    if (bark?.type !== "bark" || webhook?.type !== "webhook") throw new Error("夹具形状不对");

    expect(bark.deviceKey).toBe(MASK);
    expect(bark.name).toBe("A");
    expect(webhook.token).toBe(MASK);
    expect(webhook.password).toBe(MASK);
    expect(webhook.headerValue).toBe(MASK);
    expect(webhook.username).toBe("u-1");
    expect(webhook.headerName).toBe("X-Token");
    expect(webhook.url).toBe("https://example.test/hook");
  });

  it("原对象不被就地改写（同一份设置在域内还要以明文参与投递）", () => {
    const source = { channels: [{ ...BARK_A }] };
    redactConfig(source);
    expect(source.channels[0].deviceKey).toBe("key-a");
  });

  it("没有 channels 或 channels 不是数组时原样送出、不抛（用户层可能还没有频道；手改过的文件里它可能是字符串）", () => {
    expect(redactConfig({ notifyAsk: false })).toEqual({ notifyAsk: false });
    const broken = { channels: "oops" } as unknown as Partial<NotifyConfig>;
    expect(redactConfig(broken).channels).toBe("oops");
  });

  it("陌生频道类型原样送出、不抛（读出口报错时，用户看到的是设置页整页 500，而原因指向不了那个频道）", () => {
    const unknown = { type: "future", id: "future:a", note: "本版本不认识的频道" };
    // 存储层不受契约约束，构造这个形状必须绕过类型（这正是读出口要兜住的那一侧）。
    const stored = { channels: [unknown] } as unknown as Partial<NotifyConfig>;
    expect(redactConfig(stored).channels?.[0]).toEqual(unknown);
  });

  it("非对象项原样送出且不抛：字符串 / null / 数组都可能躺在存储层里（同一个对象守卫的两侧出口，读面原样送出、写面原样通过）", () => {
    for (const item of ["not-a-channel", null, []]) {
      const stored = { channels: [item] } as unknown as Partial<NotifyConfig>;
      expect(redactConfig(stored).channels?.[0], JSON.stringify(item)).toEqual(item);
      expect(restoredOf([bare(item)], []), JSON.stringify(item)).toEqual([item]);
    }
  });

  it("只掩字符串：非字符串值不是凭据，掩掉它等于把一个坏值换成另一个坏值（原文还在域内参与投递，改了就送不出去）", () => {
    const stored = { channels: [{ ...WEBHOOK, token: 42 }] } as unknown as Partial<NotifyConfig>;
    const channel = redactConfig(stored).channels?.[0];
    if (channel?.type !== "webhook") throw new Error("夹具形状不对");
    expect(channel.token).toBe(42);
  });

  // 掩码判据必须是「非空串」而不是「字符串」：读面把磁盘上缺席的凭据补成空串（input 的
  // asString 兜底），空串在配置里的含义是「未设置」而不是「一个空的凭据」。把它掩成占位，
  // 占位就绕过了客户端的空串剥除（值不是空串，剥不掉）一路带回写面；还原侧按 id 取回
  // 的是 undefined（磁盘上本来就没这个键），遂拒掉整批 400。真实路径：新建 webhook 保存
  // 一次成功，之后只切一下 enabled 开关就再也存不下去。
  it("只掩非空串：空串是「未设置」而不是一个空凭据，掩了它还原侧就会拒掉整批（空串必须原样透出）", () => {
    const stored = {
      channels: [{ ...WEBHOOK, token: "", password: "", headerValue: "" }],
    } as unknown as Partial<NotifyConfig>;
    const channel = redactConfig(stored).channels?.[0];
    if (channel?.type !== "webhook") throw new Error("夹具形状不对");

    expect(channel.token).toBe("");
    expect(channel.password).toBe("");
    expect(channel.headerValue).toBe("");
  });

  it("只掩非空串的另一半：非空的真凭据照旧掩码（判据放窄不得顺手把脱敏也一起关了）", () => {
    const stored = {
      channels: [{ ...WEBHOOK, token: "", headerValue: "h-1" }],
    } as unknown as Partial<NotifyConfig>;
    const channel = redactConfig(stored).channels?.[0];
    if (channel?.type !== "webhook") throw new Error("夹具形状不对");

    // 同一条频道上两个字段，两种判据：空的那侧透出，非空的那侧仍是占位。
    expect(channel.token).toBe("");
    expect(channel.headerValue).toBe(MASK);
  });
});

describe("unmaskChannels：写入口按 id 还原", () => {
  it("按 id 对齐而不是按下标（数组顺序一变，按下标就会把 A 的凭据回填进 B）", () => {
    const restored = restoredOf(
      [
        { ...BARK_B, deviceKey: MASK },
        { ...BARK_A, deviceKey: MASK },
      ],
      [BARK_A, BARK_B],
    );
    expect(restored[0].deviceKey).toBe("key-b");
    expect(restored[1].deviceKey).toBe("key-a");
  });

  it("只还原带了掩码的字段：同一次提交里新填的凭据照原样通过（用户就是要换掉旧值）", () => {
    const restored = restoredOf([{ ...BARK_A, deviceKey: "key-new" }], [BARK_A]);
    expect(restored[0].deviceKey).toBe("key-new");
  });

  it("没有密钥字段的提交整项原样通过（改个显示名不该被还原逻辑拦住）", () => {
    const restored = restoredOf([{ id: "bark:a", type: "bark", name: "改名" }], [BARK_A]);
    expect(restored[0]).toEqual({ id: "bark:a", type: "bark", name: "改名" });
    expect(restoredOf(["not-a-channel"], [BARK_A])[0]).toBe("not-a-channel");
  });

  it("掩码只能表达「未修改」：没有原值可还原的掩码一律被拒（否则等于凭空造出一个凭据）", () => {
    const rows: ReadonlyArray<readonly [RawSettingValue, RawSettingValue | undefined]> = [
      [[{ ...BARK_A, id: "bark:new", deviceKey: MASK }], [BARK_A]],
      [[{ ...BARK_A, deviceKey: MASK }], [{ id: "bark:a", type: "bark", name: "无密钥字段" }]],
      [[{ ...BARK_A, deviceKey: MASK }], undefined],
      [[{ ...BARK_A, id: 42, deviceKey: MASK }], [BARK_A]],
      // 空 id 与数字 id 都不是对齐键：不能与存储里同样「没写 id」「写了数字 id」的项对上，
      // 否则会把 A 的凭据回填进 B。
      [[{ ...BARK_A, id: "", deviceKey: MASK }], [{ id: "", type: "bark", deviceKey: "key-x" }]],
      [[{ ...BARK_A, id: 42, deviceKey: MASK }], [{ id: 42, type: "bark", deviceKey: "key-42" }]],
    ];
    for (const [patch, existing] of rows) {
      expect(unmaskChannels(patch, existing), JSON.stringify(patch)).toEqual({ ok: false });
    }
  });

  it("非数组 channels 给 ok:false 而不是抛（还原跑在校验之前，抛出去就是一次未捕获的写失败）", () => {
    expect(unmaskChannels("oops", [BARK_A])).toEqual({ ok: false });
    expect(unmaskChannels(bare({ id: "bark:a" }), [BARK_A])).toEqual({ ok: false });
  });
});

packages/dsh-notifier/test/unit/config/d.source:
/**
 * dsh-notifier config 域 draft 块 —— 草稿测试（dry-run）的输入闸门（提案 B1/B2）。
 *
 * 判据面：只认 draft.channels（顶层其它键与 revision 忽略）；逐项 validateChannel 但跳过
 * requireBuiltinsPresent（单条草稿不带内置也放行）；掩码按 id 还原（新频道无源 / 改名带掩码
 * → NEW_CHANNEL_MASK_HINT）；还原后残留掩码字面量（跨 type）整体拒绝。本块是 L1 纯函数块，
 * 直引 impl/draft/index.ts；掩码字面量独立写出（与 redact.test.ts 同一跨端契约）。
 */
import { describe, expect, it } from "vitest";

import { resolveDraftChannels } from "../../../src/server/config/impl/draft/index.ts";
import type { RawSettingValue } from "../../../src/server/config/impl/model/type.ts";

/** 掩码占位：与设置页共享的契约字面量（独立抄写，见 redact.test.ts 模块头）。 */
const MASK = "********";

/** 已存 bark 频道（还原原值来源）。 */
const STORED_BARK = {
  type: "bark",
  id: "bark-1",
  baseUrl: "https://api.day.app",
  deviceKey: "real-key",
  enabled: true,
};

/** 已存 webhook 频道。 */
const STORED_WEBHOOK = {
  type: "webhook",
  id: "webhook-1",
  url: "https://example.test/hook",
  auth: "bearer",
  token: "real-token",
  enabled: true,
};

function secretsOf(...channels: unknown[]): readonly RawSettingValue[] {
  return channels as readonly RawSettingValue[];
}

function hintOf(draft: unknown, secrets?: readonly RawSettingValue[]): string {
  const resolved = resolveDraftChannels(draft, secrets);
  if (resolved.ok) throw new Error("期望拒绝，实际通过");
  return resolved.hint;
}

describe("resolveDraftChannels：只认 channels（B1）", () => {
  it("顶层其它键与 revision 一律忽略：channels 合法即通过且原样带回", () => {
    const resolved = resolveDraftChannels(
      { channels: [STORED_BARK], revision: 99, kindRoutes: { test: ["x"] }, unknown: 1 },
      secretsOf(STORED_BARK),
    );
    expect(resolved.ok).toBe(true);
    if (resolved.ok) expect(resolved.channels).toEqual([STORED_BARK]);
  });
  it("无掩码的新频道在无原值时也通过（fresh install 非掩码不拒）", () => {
    const fresh = {
      type: "bark",
      id: "bark-fresh",
      baseUrl: "https://api.day.app",
      deviceKey: "fresh-real-key",
      enabled: false,
    };
    const resolved = resolveDraftChannels({ channels: [fresh] }, undefined);
    expect(resolved.ok).toBe(true);
    if (resolved.ok) expect(resolved.channels).toEqual([fresh]);
  });

  it("draft 非对象 / channels 非数组 → 拒绝", () => {
    expect(hintOf(null, [])).toContain("draft 需要对象");
    expect(hintOf({}, [])).toContain("draft.channels 需要数组");
    expect(hintOf({ channels: "bark-1" }, [])).toContain("draft.channels 需要数组");
  });

  it("逐项校验：单条非法即整体拒绝（bark 缺 deviceKey）", () => {
    const bad = { type: "bark", id: "bark-1", baseUrl: "https://api.day.app", enabled: true };
    expect(hintOf({ channels: [bad] }, [])).toContain("缺少 deviceKey");
  });

  it("跳过 requireBuiltinsPresent：单条实例草稿不带内置也放行", () => {
    const resolved = resolveDraftChannels({ channels: [STORED_BARK] }, secretsOf(STORED_BARK));
    expect(resolved.ok).toBe(true);
    if (resolved.ok) expect(resolved.channels).toHaveLength(1);
  });
});

describe("resolveDraftChannels：掩码往返（B2）", () => {
  it("掩码按 id 还原：提交掩码即换回已存真凭据", () => {
    const draft = {
      type: "bark",
      id: "bark-1",
      baseUrl: "https://api.day.app",
      deviceKey: MASK,
      enabled: true,
    };
    const resolved = resolveDraftChannels({ channels: [draft] }, secretsOf(STORED_BARK));
    expect(resolved.ok).toBe(true);
    if (resolved.ok) {
      expect(resolved.channels[0]).toMatchObject({ deviceKey: "real-key" });
    }
  });

  it("新频道无源带掩码 → NEW_CHANNEL_MASK_HINT 拒绝", () => {
    const draft = {
      type: "bark",
      id: "bark-new",
      baseUrl: "https://api.day.app",
      deviceKey: MASK,
      enabled: false,
    };
    expect(hintOf({ channels: [draft] }, secretsOf(STORED_BARK))).toContain(
      "新增频道不能提交掩码占位",
    );
  });

  it("id 改名带掩码同样拒绝：原值按 id 对齐，改名即无源", () => {
    const draft = {
      type: "bark",
      id: "bark-renamed",
      baseUrl: "https://api.day.app",
      deviceKey: MASK,
      enabled: true,
    };
    expect(hintOf({ channels: [draft] }, secretsOf(STORED_BARK))).toContain(
      "新增频道不能提交掩码占位",
    );
  });

  it("跨 type 残留掩码 → 整体拒绝（bark→webhook 残留 deviceKey 掩码）", () => {
    const draft = {
      type: "webhook",
      id: "webhook-1",
      url: "https://example.test/hook",
      auth: "none",
      deviceKey: MASK,
      enabled: true,
    };
    expect(hintOf({ channels: [draft] }, secretsOf(STORED_WEBHOOK))).toContain("未还原的掩码占位");
  });

  it("无原值来源时任何掩码都拒绝（fresh install 也 fail-closed）", () => {
    const draft = {
      type: "webhook",
      id: "webhook-1",
      url: "https://example.test/hook",
      auth: "bearer",
      token: MASK,
      enabled: true,
    };
    expect(hintOf({ channels: [draft] }, undefined)).toContain("新增频道不能提交掩码占位");
  });
});

packages/dsh-notifier/test/unit/shared/q.source:
/**
 * dsh-notifier src/shared/quiet —— 免打扰共享面的单源判据。
 *
 * 收口起因：上限（服务端 5 / 客户端 5）与区间口径（judge parseClock+inWindow、
 * input CLOCK_PATTERN+asQuietWindow、客户端 clockToMinutesLocal+windowHitLocal）
 * 各写一份，口径一致全靠人工同步。收口后三端消费同一个绑定，「同值同口径」由构造保证；
 * 本文件再把值、口径与「各端不再有第二份字面量/第二份实现」钉成可判红的判据。
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, describe, expect, it, vi } from "vitest";

import {
  QUIET_WINDOWS_LIMIT,
  inWindowMinutes,
  isClockText,
} from "../../../src/shared/interface.ts";
import { QUIET_WINDOWS_LIMIT as MODEL_LIMIT } from "../../../src/server/config/impl/model/type.ts";
import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import { normalizeConfig, validateSettings } from "../../../src/server/config/impl/input/index.ts";
import { inWindow, judgeRequest } from "../../../src/server/pipeline/impl/judge/index.ts";

const pkgDir = fileURLToPath(new URL("../../../", import.meta.url));

afterEach(() => {
  vi.useRealTimers();
});

describe("上限单源：两端读同一个数", () => {
  it("共享值钉住 5，模型侧只是转出（改一边即红）", () => {
    expect(QUIET_WINDOWS_LIMIT).toBe(5);
    expect(MODEL_LIMIT).toBe(QUIET_WINDOWS_LIMIT);
  });

  it("客户端不再抄一份 VIEW 常量", () => {
    const src = readFileSync(join(pkgDir, "src/client/settings/panes/events.tsx"), "utf8");
    expect(src).not.toMatch(/QUIET_WINDOWS_LIMIT_VIEW/u);
    expect(src).toContain("QUIET_WINDOWS_LIMIT");
    expect(src).toContain('from "../../../shared/interface.ts"');
  });
});

describe("命中口径三端同表：共享 / 裁决同行", () => {
  it.each<[number, string, string, boolean]>([
    [23 * 60, "22:00", "08:00", true],
    [8 * 60, "22:00", "08:00", false],
    [22 * 60, "22:00", "08:00", true],
    [13 * 60 + 30, "13:00", "14:00", true],
    [14 * 60, "13:00", "14:00", false],
    [12 * 60, "12:00", "12:00", false],
    [12 * 60, "25:00", "08:00", false],
    [12 * 60, "22:00", "nope", false],
  ])("inWindowMinutes(%i, %s, %s) = %s，且裁决侧同行", (minutes, start, end, hit) => {
    expect(inWindowMinutes(minutes, start, end)).toBe(hit);
    expect(inWindow(minutes, start, end)).toBe(hit);
  });

  it("时钟形状两端同源：合法放行、非法拒绝", () => {
    for (const clock of ["00:00", "22:00", "23:59"]) expect(isClockText(clock)).toBe(true);
    for (const clock of ["24:00", "22:60", "9:30", "abc", "", "22:00:00"]) {
      expect(isClockText(clock)).toBe(false);
    }
  });

  it("写面与读面同口径：合法窗口放行，非法/零长拒绝或丢项", () => {
    expect(
      validateSettings({
        quietHours: { enabled: true, windows: [{ start: "22:00", end: "08:00" }] },
      }),
    ).toEqual({ ok: true });
    for (const windows of [
      [{ start: "25:00", end: "08:00" }],
      [{ start: "22:00", end: "22:00" }],
    ]) {
      const verdict = validateSettings({ quietHours: { enabled: true, windows } });
      if (verdict.ok) throw new Error("期望判非法，实际放行：" + JSON.stringify(windows));
      expect(verdict.error.key).toBe("quietHours");
    }
    // 读面：非法单项只废该项，合法窗口保留；显式 [] 保持 []（空数组 = 未命中）。
    const kept = normalizeConfig({
      quietHours: {
        enabled: true,
        windows: [
          { start: "nope", end: "08:00" },
          { start: "22:00", end: "08:00" },
        ],
      },
    });
    expect(kept.quietHours.windows).toEqual([{ start: "22:00", end: "08:00" }]);
    expect(
      normalizeConfig({ quietHours: { enabled: true, windows: [] } }).quietHours.windows,
    ).toEqual([]);
  });

  it("裁决脏项不抛：非对象单项按未命中跳过（活链上不抛，见 judge 文件头）", () => {
    vi.setSystemTime(new Date(2026, 0, 15, 23, 0, 0));
    const dirty = {
      ...DEFAULT_CONFIG,
      quietHours: {
        enabled: true,
        windows: ["x", null, 42, { start: "22:00", end: "08:00" }] as unknown as {
          start: string;
          end: string;
        }[],
      },
    };
    expect(() => judgeRequest(dirty, { kind: "done", title: "t", body: "b" }, true)).not.toThrow();
    expect(judgeRequest(dirty, { kind: "done", title: "t", body: "b" }, true)).toEqual({
      ok: false,
      reason: "quiet",
    });
    const allDirty = {
      ...DEFAULT_CONFIG,
      quietHours: {
        enabled: true,
        windows: ["x", null] as unknown as { start: string; end: string }[],
      },
    };
    expect(judgeRequest(allDirty, { kind: "done", title: "t", body: "b" }, true)).toEqual({
      ok: true,
    });
  });

  it("客户端回显走共享命中，不再自备区间实现", () => {
    const src = readFileSync(join(pkgDir, "src/client/settings/panes/events.tsx"), "utf8");
    expect(src).not.toMatch(/function windowHitLocal/u);
    expect(src).not.toMatch(/function clockToMinutesLocal/u);
    expect(src).toContain("inWindowMinutes");
  });
});

packages/dsh-notifier/test/unit/config/m.source:
/**
 * dsh-notifier config 域 model 块 —— 默认形态与布尔键清单。
 *
 * 为什么默认值要在这里用手写字面量再写一遍：本域其余用例的期望值都取自 `DEFAULT_CONFIG[key]`
 * 本身，而实现的回落源就是同一个对象——两侧同源同变，把 `notifyAsk: true` 改成 `false` 之后
 * 全套测试照样绿。而默认值同时是设置页的初始形态与跨端契约（客户端按同一份形状渲染），
 * 不能是「实现说什么就是什么」：它必须有一份独立于实现的书面形态。
 *
 * `BOOLEAN_KEYS` 同理——它是校验闸门的分支依据，漏登记一个键就等于该键的布尔闸门静默消失
 * （陌生键落到校验的兜底出口即放行），故清单也在测试里手写一份，两边逐字对齐。
 *
 * 本块是 L1 纯函数块，直引 `impl/model/index.ts` 与 `impl/input/index.ts`。
 */
import { describe, expect, it } from "vitest";

import {
  BOOLEAN_KEYS,
  normalizeConfig,
  validateSettings,
} from "../../../src/server/config/impl/input/index.ts";
import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import type { RawSettingValue } from "../../../src/server/config/impl/model/type.ts";

/** 手写默认形态：与实现零共享（不 import 它的任何取值），改动默认值必须在这里也显式改一次。 */
const EXPECTED_DEFAULTS = {
  notifyAsk: true,
  notifyQuestion: true,
  notifyTaskDone: true,
  notifySubagentDone: false,
  notifyTaskError: true,
  notifyTurnEnd: false,

  quietHours: { enabled: false, windows: [{ start: "22:00", end: "08:00" }] },
  // 两条内置频道是默认形态的一部分：读面靠它们才谈得上「与默认表逐字一致」，权威形态也住在它们身上。
  channels: [
    { type: "browser", id: "browser", enabled: true, popup: true, sound: true, whenVisible: false },
    { type: "system", id: "system", enabled: true, popup: true, sound: true },
  ],
  kindRoutes: {},
  allowKinds: [],

  historyMaxAgeDays: 0,
} as const;

/** 受布尔闸门管的键：手写清单，与实现的 `BOOLEAN_KEYS` 是两份独立文本。 */
const BOOLEAN_SETTING_KEYS: readonly string[] = [
  "notifyAsk",
  "notifyQuestion",
  "notifyTaskDone",
  "notifySubagentDone",
  "notifyTaskError",
  "notifyTurnEnd",
];

describe("DEFAULT_CONFIG：默认形态以手写字面量为准，不由实现自述", () => {
  it("整份默认设置等于手写形态：布尔偏置、两条内置条目与计数/列表类默认值逐个锚住（改坏一行不该悄无声息）", () => {
    expect(DEFAULT_CONFIG).toEqual(EXPECTED_DEFAULTS);
  });

  it("空输入归一化后与默认表逐字相等：默认表同时是读面的物化基准（两侧不等就说明物化补了默认表没有的东西）", () => {
    expect(normalizeConfig({})).toEqual(DEFAULT_CONFIG);
  });

  it("quietHours 只有 enabled / windows：allowKinds 缺省表示「时段内不额外放行谁」（整体相等看不出多出来的键值是 undefined）", () => {
    expect(Object.keys(DEFAULT_CONFIG.quietHours)).toEqual(["enabled", "windows"]);
    expect("allowKinds" in DEFAULT_CONFIG.quietHours).toBe(false);
  });
});

describe("BOOLEAN_KEYS：布尔闸门的清单必须覆盖每个布尔键", () => {
  it("清单逐字一致，且清单里每个键的非布尔值都被拦下并指向它自己（漏登记一个键 = 该键的闸门静默消失）", () => {
    expect([...BOOLEAN_KEYS].sort()).toEqual([...BOOLEAN_SETTING_KEYS].sort());

    for (const key of BOOLEAN_SETTING_KEYS) {
      const patch: Record<string, RawSettingValue> = { [key]: 1 };
      const verdict = validateSettings(patch);
      if (verdict.ok) throw new Error(`${key} 的非布尔值被判放行`);
      expect(verdict.error.key, key).toBe(key);
      expect(verdict.error.hint, key).toContain("true 或 false");
    }
  });
});
